window.harnessChunks["rows-553077f434b6d10b.js"]=["<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-17T03:12:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/open-gsd/gsd-core\" target=\"_blank\" rel=\"noopener\">get-shit-done</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-16\">2026-09-16</time></td><td class=\"review-ref\"><a href=\"https://github.com/open-gsd/gsd-core/tree/4f487e4e75276ad50fc13796cef8d23148cd8830\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 4f487e4e75276ad50fc13796cef8d23148cd8830\">4f487e4 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: executor agents autonomously implement bounded plans, modify the codebase, run checks and commit artifacts in the standard phase flow.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: dependency waves, declared dependson, file-overlap checks, worktree isolation and sequential fallback prevent conflicting execution. They do not constitute an agent-owned mutual-adjustment loop that observes and dampens ongoing interference among operational peers.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: the phase orchestrator sequences plans, gates and artifacts, but its current-whole behavior is a predetermined workflow/control plane rather than an autonomous managerial actor with decision rights over shared resources, commitments and priorities. Planner/executor supervision therefore does not by itself establish Beer S3.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: execute-phase obligatorily spawns a separate gsd-verifier after execution. The verifier receives fresh context, reads plans/summaries/requirements but is explicitly told not to trust executor summaries, inspects the actual codebase goal-backward, and produces a distinct VERIFICATION.md verdict. A non-passing result prevents phase completion; gaps are converted into gap-closure plans, re-executed, and then re-verified. This provides an independent, agent-owned audit path with a concrete corrective closure loop.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: research, discussion and planning roles gather information useful to a phase, but at the pinned revision they remain project/task-local preparation. There is no persistent agent-owned function that continuously models the external/future environment, compares it with internal capability and drives organizational adaptation into S3.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: phase goals, roadmap success criteria, project decisions, workflow rules and acceptance policy are supplied by the user/project or fixed by GSD. No agent is granted final authority to define or reconcile organizational identity, purpose or constitutional policy.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/ff74c380425fb7c8a9cee512289cdb428d74dbb1/assessments/get-shit-done.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit ff74c380425fb7c8a9cee512289cdb428d74dbb1\">ff74c38 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-10-02T00:16:23+03:00\"><th scope=\"row\"><a href=\"https://github.com/Tianshi-Xu/Life-Harness\" target=\"_blank\" rel=\"noopener\">Life-Harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-01\">2026-10-01</time></td><td class=\"review-ref\"><a href=\"https://github.com/Tianshi-Xu/Life-Harness/tree/22c299b83d888405d34d2c7efc0fcf4d2ccfdcef\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 22c299b83d888405d34d2c7efc0fcf4d2ccfdcef\">22c299b &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: execute an open-ended model-driven benchmark task through repeated model action, tool/environment response and harness-mediated corrective feedback until completion or bounded termination. - Disturbance / variety regulated: task instructions, environment/database state, invalid or incomplete tool actions, tool results/errors, recurring loops, procedural mistakes, prompt/tool-contract ambiguity and runtime step limits. - Decisive decision or feedback right: choose the substantive next task action/tool call or response after observing the current conversation and the harness-mediated environment result. - Decision owner: the configured autonomous agent LLM invoked by the shipped benchmark runner. - Supporting / enforcement mechanisms: TauBench task runner, H2 HarnessRule validation, H3 tool-description contracts, H4 post-execution annotations/stuck-loop guidance, H5 skill injection, environment/tool execution and episode/result capture. - Closure path: task + current context → model chooses a substantive action/tool call → H2 may validate/reject and the environment executes permitted action → H4/environment returns error/result/annotation and H5/H3 context remains available → the next model turn observes that evidence and revises/continues → completed episode/result is recorded. - Boundary reachability: TauBench/scripts/evalharness.py is the documented standard evaluation path and directly invokes the bundled runner with the configured agent model and H2-H5 switches; the first-party harness mixins return their interventions into the agent-visible tool-result path. No downstream orchestration package is needed beyond a configured provider endpoint. - Why this is / is not agent-owned: deterministic harness rules can constrain or enrich actions but do not choose the task solution. Removing the model actor while keeping H2-H5 leaves validation/annotation machinery but removes the same substantive next-action right. - Evidence: README.md; TauBench/scripts/evalharness.py; TauBench/src/tau2/harness/base.py. - Basis: explicit + structural. - Confidence: high. - Caveats: model inference may be served externally; credit rests on the first-party operational organization that concretely closes model decision → tool/environment result → agent-visible feedback.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party inter-S1 disturbance-attenuation function is established at the campaign recursion. - Disturbance / variety regulated: not established as a concrete interaction-generated conflict or oscillation between distinct sibling operational S1 units. - Decisive decision or feedback right: not established for S2. - Decision owner: not established. - Supporting / enforcement mechanisms: evaluation concurrency, task batching, isolated worktrees/run directories, candidate screening and plugin-chain ordering coordinate execution mechanics but are not an S2 relation among mutually interacting S1 units. - Closure path: not applicable for the negative finding. - Why this is / is not agent-owned: parallel benchmark episodes do not communicate or interfere in a way that the system detects and attenuates through an S2-specific feedback loop; they are independent measurements whose aggregate evidence feeds S4. - Evidence: meta/lifeloop.py; meta/agentbenchloop.py; README.md. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: concurrency and multiple tasks are not counted as multiple coordinated S1 units without a concrete interaction disturbance and attenuation path.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct whole-system inside-and-now control function is established above operational episodes and the prospective adaptation loop. - Disturbance / variety regulated: run state, candidate lifecycle, evaluation failures, concurrency, task pools, search budgets and acceptance thresholds are controlled, but those controls are deterministic lifecycle/enforcement or belong to S4 adaptation selection. - Decisive decision or feedback right: no separate substantive authority is established over multiple current operational commitments/resources/priorities at the campaign recursion. - Decision owner: not established for S3. - Supporting / enforcement mechanisms: run configuration fingerprints, protocol freezing, task-pool selection, concurrency bounds, screen/full gates, rollback, resume state and finalization freeze. - Closure path: not applicable for the negative finding. - Boundary reachability: all listed controls are first-party and reachable, but they do not constitute a distinct S3 organizational function. - Whole-system current view: run/state files expose accepted chain, scores, task cache/history and iteration state, but that view is primarily used to choose/verify future harness changes rather than regulate a set of simultaneous current organizational commitments. - Current-control decision scope: deterministic campaign lifecycle and candidate acceptance/rollback under configured rules; no separate present-tense resource/commitment/priority judgment owner is established. - Why this is / is not agent-owned: the model-backed proposer owns future capability proposals mapped to S4. Reclassifying candidate acceptance/search control as S3 would double-count the adaptation mechanism rather than establish a distinct current-control loop. - Evidence: meta/lifeloop.py; meta/agentbenchloop.py. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: H4 stuck-loop guidance is local S1 regulation; full-pool confirmation/rollback governs candidate adaptation, not an independent S3 metasystem.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: independently evaluate an operational episode/candidate against benchmark-native outcome evidence and return discrepancy/performance feedback into later candidate regulation and adaptation. - Disturbance / variety regulated: the model-driven S1 can produce a plausible-looking trajectory/tool history that nevertheless violates benchmark ground truth, deterministic assertions, task success conditions or an independent judge criterion; a candidate harness can also regress previously passing tasks. - Decisive decision or feedback right: determine benchmark reward/per-task success for completed operational episodes and expose that outcome to the outer selection/adaptation loop. - Decision owner: constructor-dependent. Life-Harness wires a distinct benchmark/evaluator path and consumes its result, but the actual criterion may be deterministic ground truth, environment assertions or a configured benchmark judge rather than one packaged autonomous auditor common to every supported environment. - Supporting / enforcement mechanisms: meta/benchmark.py, benchmark-native evalharness.py/AgentBench evaluators, harnesssummary.json, per-task reward maps, full-pool confirmation, regression sentries, infrastructure-error rejection and frozen split/task contracts. - Closure path: operational model/harness produces a trajectory/result → separate benchmark-native evaluator checks it against task/environment criteria and emits reward/per-task evidence → Life-Harness outer loop uses the evidence to reject/accept/rollback a candidate and records the resulting trajectory/evaluation state → later proposer iterations consume that evidence and later S1 runs use the resulting accepted chain. - Boundary reachability: every normal lifeloop candidate evaluation invokes meta/benchmark.py, which in turn calls the shipped benchmark evaluator and extracts its summary; AgentBench&#39;s current loop similarly calls a separate evaluation phase. The path is part of the standard iteration workflow, not repository CI or a paper-only analysis. - Claim being audited: that the operational episode/candidate actually satisfies the benchmark task/environment criterion and that a proposed harness change does not merely look plausible while reducing measured task success. - Ordinary reporting path: the frozen model-driven agent emits actions/messages/tool interactions and an episode result/trajectory. - Complementary access path: benchmark-native reward/assertion/judge logic and per-task outcome state not defined by the operational actor&#39;s own self-report. - Independence boundary: evaluation is executed as a separate host/benchmark path from the operational model actor; exact judge/model independence varies by domain/configuration, so the generic distribution is constructor-owned rather than A. - Who acts on findings: deterministic selection logic rejects/accepts/rolls back candidates from evaluator scores, and the model-backed proposer receives prior trajectory/outcome evidence when generating later adaptation options. - Why this is / is not agent-owned: the first-party repository provides the S3-specific separation and return path, but the decisive audit criterion is benchmark/configuration dependent rather than owned by one autonomous first-party auditor across the distribution. This supports C. - Evidence: meta/benchmark.py; meta/lifeloop.py; meta/agentbenchloop.py; TauBench/scripts/evalharness.py. - Basis: explicit + structural. - Confidence: high. - Caveats: screen sentries or held-out testing alone are not credited as S3. Credit rests on the normal separate benchmark-evaluation path plus its return into candidate regulation/adaptation; exact independence remains benchmark-specific.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: convert recurring external task/environment outcome evidence into persistent H2-H5 runtime adaptations that change how the frozen operational model behaves on later episodes. - Disturbance / variety regulated: repeated action-format failures, wrong tool conventions, missing fields, loops/no-ops, premature submissions, procedural mistakes, benchmark performance gaps and regressions observed across earlier episodes. - Decisive decision or feedback right: choose the concrete next persistent harness intervention — its target layer, mechanism and code — from prior trajectory/evaluation evidence. - Decision owner: the configured model-backed proposer agent invoked through the first-party meta/proposer.py wrapper and constrained by the Life-Harness evolution prompt/evidence contract. - Supporting / enforcement mechanisms: evolution prompt, bounded trajectory/evidence exposure, Qoder proposer wrapper, candidate plugin contract, H2-H5 registries/hooks, candidate validation, screen/full evaluation, strict acceptance/rollback, persistent chain manifest/loader and resumable state/history. - Closure path: S1 episodes encounter external benchmark/environment distinctions → trajectories plus independent benchmark outcomes are persisted → the model-backed proposer inspects bounded prior evidence and autonomously writes one targeted H2-H5 candidate plugin → first-party host validates and evaluates it → accepted plugin is copied into the persistent chain/confirmed state → later operational episodes load that changed harness behavior → their outcomes seed the next adaptation cycle. - Boundary reachability: README.md documents meta/lifeloop.py and meta/agentbenchloop.py as the current iteration commands; those loops directly call proposer.run, automatically evaluate generated candidate files and persist accepted content. Qoder/provider implementation is an external dependency, but the first-party standard path concretely installs it as the decisive adaptation actor rather than leaving evolution to an unspecified downstream integration. - Why this is / is not agent-owned: deterministic host logic chooses when/how to validate and whether measured improvement crosses the configured gate, but it does not decide what failure mechanism to target or what code change to make. Removing the model-backed proposer while preserving screening, evaluation and state machinery removes the same substantive adaptation-option judgment. - External distinction: benchmark task trajectories, environment/tool outcomes, per-task rewards, failure groups and regression evidence describe where the present harness succeeds/fails in the external task distribution. - Future / prospective distinction: each accepted plugin is retained specifically to alter behavior on later episodes; the proposer is instructed to diagnose recurring patterns and implement reusable interventions rather than retry the current episode. - Adaptation option generated: a concrete self-contained plugin that modifies one or more H2 action-realization, H3 environment-contract, H4 trajectory-regulation or H5 procedural-skill surfaces. - Path back into current capability / S3: after full confirmation, the candidate is copied into the ordered accepted chain (or into the frozen AgentBench incumbent), the loader/state is updated, and subsequent evaluation/operational episodes execute with that persistent changed interface. - Evidence: README.md; meta/lifeloop.py; meta/agentbenchloop.py; meta/proposer.py; TauBench/src/tau2/harness/base.py. - Basis: explicit + structural. - Confidence: high. - Caveats: published performance gains are not used to infer ownership. The operator selects model/task/configuration and launches the campaign; that does not establish a distinct parent S4 mode because ordinary launch/configuration is not a returned adaptation judgment.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no closed first-party runtime path is established for deciding or reaffirming the campaign&#39;s ultimate identity, purpose or foundational policy. - Disturbance / variety regulated: operator-selected benchmark/domain, task pool, models, proposer budget, H2-H5 mutation contract, forbidden references, allowed tools, acceptance thresholds and held-out rules strongly constrain evolution but are externally authored mandate/enforcement. - Decisive decision or feedback right: no first-party actor is shown receiving an identity/ultimate-policy issue, deciding the foundational mandate and returning that authoritative decision into operation. - Decision owner: not established for S5. - Supporting / enforcement mechanisms: CLI/run configuration, frozen protocol/config fingerprints, proposer tool allowlists, read-only/forbidden-reference guards, H2-H5 search-space constraints, acceptance rules and finalization freeze. - Closure path: not applicable; no identity/policy issue → legitimate ultimate authority → authoritative decision → returned governance path is established. - Why this is / is not agent-owned: the proposer may autonomously change permitted operational interface content, but its prompt explicitly forbids changing model weights, benchmark tasks, environment/evaluation criteria and hidden policy boundaries. Capability self-improvement inside that mandate is S4, not authority to redefine the mandate itself. - Evidence: meta/lifeloop.py; meta/agentbenchloop.py; meta/proposer.py; README.md. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: strong anti-cheat/security/search-space rules are enforcement, not S5 ownership. Human ability to alter source/configuration outside the run is not a complete parent S5 loop at this recursion.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/97f0a1776f3c859ba1cb65e623a976de8b8dc29e/assessments/life-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 97f0a1776f3c859ba1cb65e623a976de8b8dc29e\">97f0a17 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-10-04T15:23:37+03:00\"><th scope=\"row\"><a href=\"https://github.com/moonbitlang/openseek\" target=\"_blank\" rel=\"noopener\">OpenSeek</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-04\">2026-10-04</time></td><td class=\"review-ref\"><a href=\"https://github.com/moonbitlang/openseek/tree/3999e3c1a804651f7d59b2f69dad6c6dae48de71\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 3999e3c1a804651f7d59b2f69dad6c6dae48de71\">3999e3c &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: perform environment-facing software-engineering work by interpreting a task, selecting coding/tool actions, executing them through the first-party runtime, observing their results and iterating until completion or another terminal condition. - Disturbance / variety regulated: heterogeneous repositories and objectives, changing file/Git/process state, compiler/test output, tool failures, model observations, user steering, background-job completion and task-specific implementation choices. - Decisive decision or feedback right: decide what evidence to inspect, which coding/control/MCP action to take next, how to revise work from returned observations, and when to finish, continue or report standing-goal status within externally selected runtime constraints. - Decision owner: the main model-backed OpenSeek agent instantiated by the first-party turn loop. - Supporting / enforcement mechanisms: agent loop; typed tool registry; mbtx; file/edit/write/remove tools; plan/goal/finish; durable session/store; steering queue; context compaction; skills/MCP; approval/sandbox policy; run/serve transports. - Closure path: user task + workspace/session state → main model selects tool/action → OpenSeek executes or gates it → tool/environment result is appended to the authoritative session → the updated session projection returns to the main model → next action or terminal decision. - Boundary reachability: standard openseek run and openseek serve directly instantiate the first-party model/tool loop and built-in tools; no downstream application-authored orchestration layer is required. - Why this is / is not agent-owned: deterministic runtime code transports, persists and enforces selected actions, but removing the main model-backed actor removes the open-ended software-engineering judgment that chooses and sequences those actions. - Evidence: agent/README.mbt.md; docs/architecture.md; cmd/openseek/README.md. - Basis: explicit + structural. - Confidence: high. - Caveats: model inference is an external provider dependency; OpenSeek is credited for its shipped actor/tool/feedback organization rather than provider internals.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party same-recursion inter-S1 coordination function was established. - Disturbance / variety regulated: not established at S2 level. OpenSeek can launch bounded hosted child agents/scouts/reviewers, but the frozen standard distribution does not establish a concrete mutual interference, conflict or oscillation among distinct production S1 units that a first-party coordination relation specifically attenuates. - Decisive decision or feedback right: not established. - Decision owner: not established. - Supporting / enforcement mechanisms: hosted child/subrun transport; child-session identity; workflow delegation; task-group/runtime queues; review/scout results; session locks and sequential turn processing. - Closure path: not applicable; no distinct-production-S1 interference → attenuation decision → changed subsequent S1 behaviour loop was reconstructed. - Why this is / is not agent-owned: delegation and concurrent bounded investigation move work/results between actors but are not S2 without a specific interference witness and attenuation relation. - Evidence: cmd/openseek/README.md; agent/README.mbt.md; agentreview/README.mbt.md. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: a larger application can compose several OpenSeek workers into an organization with S2; that organization is outside this standalone engine/session boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no material first-party whole-organization current-control function distinct from the main coding S1 and deterministic run/session controls was established. - Disturbance / variety regulated: active goal state, current plan, tool/background-job progress, context/step ceilings, approvals, cancellation and session sequencing are regulated operationally, but not as a whole-system portfolio of multiple operational commitments/resources. - Decisive decision or feedback right: not established at S3 level. Main-agent plan/goal choices remain part of executing the current task, while runtime scheduling, bounds and approval machinery enforce configured/operator policy. - Decision owner: not established. - Supporting / enforcement mechanisms: plan/goal tools; standing-goal reminders; task groups; step/context ceilings; serve queue; cancellation/steering; approval desk; background-job controls; session persistence. - Closure path: not applicable; no whole-system current view plus substantive current-control decision over multiple relevant S1 resources, commitments, priorities or accountability was found. - Why this is / is not agent-owned: the main model owns coding-task decisions, not a distinct metasystem current-control role over an organization of S1s. Deterministic runtime controls continue to enforce their configured bounds without an autonomous managerial owner. - Evidence: agent/turnloop.mbt; docs/architecture.md; cmd/openseek/README.md. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: this does not deny substantial current-task supervision and lifecycle control; the negative conclusion is specific to the Profile&#39;s stronger whole-system S3 function at this recursion.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: independently challenge a main-agent standing-goal completion claim using complementary read-only worktree/compiler evidence and return the audit finding into the same coding organization before subsequent main-agent action. - Disturbance / variety regulated: a producing coding agent may report a goal as met while the actual worktree, diff, compiler/test state or goal criteria reveal incomplete, incorrect or superficially satisfying work. - Decisive decision or feedback right: decide, from an independently modelled read-only audit of the worktree against the goal/baseline, what findings exist and submit the structured ReviewReport that becomes the audit verdict returned to the main run. - Decision owner: the separate model-backed agentreview child in the supported review-gate mode. - Supporting / enforcement mechanisms: run --kind review; read-only mbtx profile; compiler/test execution; structured submitreview; report validation at child and parent trust boundaries; captured goal baseline; child step/deadline bounds; durable review runtime notice; main-loop pending-review scheduler. - Closure path: main S1 records goal(met) → OpenSeek schedules a separate review child → reviewer independently inspects the live worktree against the goal/baseline and submits a validated report → gate converts it to a review digest → digest is durably appended and mirrored into the main agent&#39;s messages → next main-agent request sees the audit and can revise/reconfirm work. - Boundary reachability: --review-gate is a first-party option shared by supported run and serve modes; it wires the shipped agentreview child directly into the main turn. No external reviewer service or downstream orchestration code is required. - Why this is / is not agent-owned: deterministic code launches and validates the audit, but the substantive review judgment and findings are generated by a distinct model-backed reviewer. Removing that reviewer leaves only transport/validation and no semantic audit verdict. - Evidence: agentreview/README.mbt.md; internal/openseek/options/review.mbt; internal/openseek/execution/gate.mbt; internal/openseek/run/turn.mbt; agent/goalgatetest.mbt; agent/turnloop.mbt. - Basis: explicit + structural. - Confidence: high. - Caveats: the gate is opt-in and advisory/fail-open; A therefore describes the supported first-party audit ownership mode, not a claim that every OpenSeek run is audit-gated or that reviewer availability is guaranteed. - Claim being audited: the producing main agent&#39;s claim that the current standing goal is met. - Ordinary reporting path: the main agent&#39;s own goal(met) / finish path in the active coding session. - Complementary access path: the separate agentreview child reads the current worktree against the captured goal/baseline through a read-only tool profile and grounds findings in compiler/test evidence rather than relying on the producing agent&#39;s report. - Independence boundary: the audit is a distinct child model run with its own bounded session/allowance and a no-edit review toolset; the gate reads the live standing goal/baseline from authoritative session state, so the audited S1 does not restate the criteria to the reviewer. - Who acts on findings: the main coding agent. The review digest is appended as a durable runtime notice and injected into the next model request; frozen-revision tests verify that same-batch completion continues through the gate and the post-gate model request sees the audit.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party outside-and-future intelligence loop that generates and adopts an organizational adaptation was established. - Disturbance / variety regulated: not established at S4 level. Durable history, compaction, skills, MCP, web/search-like tools, review findings and resumable goals improve present/future task context but do not by themselves model environmental change and alter OpenSeek&#39;s persistent organizational capability/strategy. - Decisive decision or feedback right: not established. - Decision owner: not established. - Supporting / enforcement mechanisms: append-only session memory; compaction summaries; skills; MCP; review reports; durable goals; provider/model/runtime configuration. - Closure path: not applicable; no first-party external/future distinction → adaptation-option generation → autonomous selection → persistent capability/strategy change → later operation loop was found. - Why this is / is not agent-owned: retained information and audit feedback can change the current task, while installed skills/configuration can change capability under operator/developer control. Neither establishes an autonomous prospective adaptation owner. - Evidence: docs/architecture.md; README.md; agent/README.mbt.md. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: users can author workflows that research and change a project or agent setup; generic composability is not a first-party S4 closure.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material first-party identity/ultimate-policy decision loop was established. - Disturbance / variety regulated: prompts, approval policy, workspace/tool restrictions, model/provider selection, MCP configuration and runtime bounds constrain behavior, but they are operating configuration/enforcement rather than a reconstructed identity-level governance function. - Decisive decision or feedback right: not established for an identity/ultimate-policy issue. - Decision owner: user/operator/developer configuration for the relevant constraints; deterministic OpenSeek machinery enforces those selections and the agent acts inside them. - Supporting / enforcement mechanisms: system prompt selection; approval policy/channel; workspace/tool boundaries; model/provider/API settings; MCP configuration; goal/review options; cancellation. - Closure path: not applicable at S5 level; configuration can govern later behavior, but no standard identity/policy conflict → legitimate ultimate authority → authoritative decision → returned operation loop was established. - Why this is / is not agent-owned: the main or review model does not own OpenSeek&#39;s ultimate identity/policy boundary, and hard enforcement of externally selected constraints is not itself S5 ownership. - Evidence: cmd/openseek/README.md; agent/README.mbt.md; internal/openseek/run/turn.mbt. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: a deployment can place OpenSeek under an external parent organization&#39;s policy; that parent is not imported into this standalone first-party assessment without a function-specific closed mode.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/ebd85b1e0092ebea5d8dcadaa6e59fd75b7f1864/assessments/openseek.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit ebd85b1e0092ebea5d8dcadaa6e59fd75b7f1864\">ebd85b1 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-10-05T20:48:25+03:00\"><th scope=\"row\"><a href=\"https://github.com/liwenka1/deep-code\" target=\"_blank\" rel=\"noopener\">deep-code</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-05\">2026-10-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/liwenka1/deep-code/tree/94199de128d259ad513275db3e84433299a58a9a\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 94199de128d259ad513275db3e84433299a58a9a\">94199de &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously perform coding work through iterative model/tool decisions against the live workspace. - Disturbance / variety regulated: unfamiliar codebase state, incomplete requirements, command/build/test failures, tool errors, model/provider failures, context growth and permission/sandbox constraints. - Decisive decision or feedback right: choose the next repository/tool action, revise the approach after returned evidence, delegate bounded sub-tasks and decide when the requested coding work is complete. - Decision owner: the active model-backed deep-code parent agent; bounded child agents own their delegated local decisions. - Supporting / enforcement mechanisms: runtime turn loop, first-party tool registry, workspace/shell/web/debug/LSP tools, model routing/retry, approvals, sandbox policy, sessions/checkpoints, compaction and sub-agent execution. - Closure path: task/context → model selects tool/coding action → runtime/tool returns concrete evidence → evidence re-enters the model context → later action changes until completion, cancellation or bounded failure. - Boundary reachability: the standard TUI/headless/server product paths directly instantiate the same first-party runtime and tool loop. - Why this is / is not agent-owned: removing the model actor leaves tools, policy, persistence and sandboxing but removes the open-ended decisions that transform evidence into coding actions. - Evidence: README; crates/deep-code-agent/src/runtime/turnloop.rs; crates/deep-code-agent/src/tool/registry.rs; crates/deep-code-agent/src/runtimelaunch.rs; crates/deep-code-agent/src/subagent/tools.rs. - Basis: explicit + structural. - Confidence: high. - Caveats: external inference remains a dependency; safety/approval machinery constrains but does not own the coding objective.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no distinct first-party relation is established that attenuates a specific interference or oscillation among distinct operational S1 units. - Disturbance / variety regulated: several child agents can run in parallel and implementer children may share the same parent workspace, but the frozen runtime does not expose a peer-collision detection/negotiation loop or shared-resource coordination authority among them. - Decisive decision or feedback right: no S2-specific choice over inter-S1 conflict or mutual adjustment was found. - Decision owner: not established at S2 level. - Supporting / enforcement mechanisms: blocking agent calls, child role/tool restrictions, approval gates, timeouts, manager records and parent-side task briefs. - Closure path: children execute bounded delegated tasks and return reports; deterministic restrictions constrain each child but do not close a specific peer-interference attenuation loop. - Why this is / is not agent-owned: delegation, parallel execution, permissions and shared workspace state are not S2 without an evidenced inter-S1 disturbance plus coordinating feedback. - Evidence: README; crates/deep-code-agent/src/subagent/tools.rs; subagent/manager.rs; subagent/runner.rs; subagent/roles.rs. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: parallel implementers can create practical write interference, but the reviewed runtime does not demonstrate a first-party coordination function that detects and attenuates that disturbance.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct whole-system current-control function over a standing portfolio of operations is established. - Disturbance / variety regulated: the parent can choose child tasks and observe returned reports, while runtime limits track child status and timeout/cancellation. - Decisive decision or feedback right: no separate authority has a whole-system current view plus substantive control over a persistent set of current S1 commitments/resources/priorities on behalf of the whole. - Decision owner: not established at S3 level. - Supporting / enforcement mechanisms: parent agent tool calls, sub-agent manager records, child timeout/cancellation, session/status surfaces and model routing. - Closure path: an agent tool call blocks until the child returns; the result becomes ordinary evidence in the parent S1 loop rather than a distinct persistent whole-current management cycle. - Why this is / is not agent-owned: model-driven delegation is part of the parent operational strategy; bookkeeping and cancellation are runtime enforcement, not a metasystemic current-control owner. - Evidence: crates/deep-code-agent/src/subagent/tools.rs; subagent/manager.rs; README; runtime state/session surfaces. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: /agents and manager records provide observability, but observability plus bounded blocking delegation is insufficient for S3.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: independently challenge implementation/correctness claims by direct read-only inspection or verification and return findings to the producing parent agent. - Disturbance / variety regulated: implementation defects, incorrect assumptions and unverified completion claims that may survive the producer&#39;s own reasoning. - Decisive decision or feedback right: the reviewer/verifier child model decides which observed evidence constitutes a material review finding or PASS/FAIL conclusion and reports that judgment to the parent. - Decision owner: the separate model-backed review or verifier child agent. - Supporting / enforcement mechanisms: fresh child context, explicit read-only role policy, role-specific review/verifier prompts, direct repository/search/read/shell access, dedicated fast-tier model selection and structured child report return. - Closure path: parent/implementer produces or proposes work → parent dispatches read-only review/verifier child → child directly inspects workspace and/or runs verification gates → structured findings/PASS-FAIL return as the agent tool result → parent changes subsequent coding/repair action based on the audit result. - Boundary reachability: review and verifier are shipped first-party role aliases accepted by the standard agent tool; no external reviewer product is required. - Why this is / is not agent-owned: removing the reviewer/verifier model leaves role restrictions and tool plumbing but removes the independent semantic judgment over inspected evidence. - Evidence: README; crates/deep-code-agent/src/subagent/roles.rs; subagent/tools.rs; subagent/runner.rs; subagent/registry.rs. - Basis: explicit + structural. - Confidence: high. - Caveats: dispatch is chosen by the parent and is not mandatory for every coding task; the positive state concerns the supported first-party complementary-audit mode.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no externally and prospectively oriented adaptation loop is established. - Disturbance / variety regulated: model routing, persistent sessions, compaction, skills/configuration and web access can change how current or later tasks are executed. - Decisive decision or feedback right: no first-party actor was found that senses external/future change, generates organizational adaptation options and installs a selected adaptation into later capability. - Decision owner: not established at S4 level. - Supporting / enforcement mechanisms: model router, skills loading, sessions/checkpoints, web tools, compaction and configuration. - Closure path: these mechanisms support current task execution, recovery or operator-selected capability, not a separate outside-and-then adaptation conversation. - Why this is / is not agent-owned: persistence, external lookup and model selection are not sufficient for S4 without prospective environmental distinction and adaptation-option closure. - Evidence: README; model-routing, skills, session and compaction modules under crates/deep-code-agent/src. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: no reviewed first-party self-evolution/update path changes reusable capability from cross-task environmental evidence.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no identity- or ultimate-policy-level closure is established. - Disturbance / variety regulated: permission modes, approval memory, hard deny floors, sandbox/write-root/network policy and role restrictions constrain ordinary execution. - Decisive decision or feedback right: no identity/ultimate-policy issue is routed to legitimate ultimate authority and returned as a durable governing system decision. - Decision owner: not established at S5 level. - Supporting / enforcement mechanisms: permission tiers, approval classifier/human approval, execution-policy engine, sandbox policy, write-root grant boundary, child role restrictions and configuration. - Closure path: these mechanisms approve/refuse specific operational actions or configure execution posture; they do not settle identity-level policy questions for subsequent system operation. - Why this is / is not agent-owned: safety policies and human approval gates are operational constraints, not S5 by themselves. - Evidence: README; approvalclassifier.rs; runtime/approvalflow.rs; executionpolicy/engine.rs; sandbox/policy.rs; subagent/roles.rs. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: the operator has meaningful authority over permissions and write/network grants, but ordinary action approval does not create an identity-level S5 return loop.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/b28736d23116b96089669c65fef57d7e82784de1/assessments/deep-code.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit b28736d23116b96089669c65fef57d7e82784de1\">b28736d &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-10-16T21:36:50+03:00\"><th scope=\"row\"><a href=\"https://github.com/Florious95/team-agent\" target=\"_blank\" rel=\"noopener\">Team Agent</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-16\">2026-10-16</time></td><td class=\"review-ref\"><a href=\"https://github.com/Florious95/team-agent/tree/1107b2881b7c55bde14a270f472db034cfefcc9a\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 1107b2881b7c55bde14a270f472db034cfefcc9a\">1107b28 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: execute bounded user software/research work via durable role-bound, Team Agent-managed autonomous specialist seats. - Disturbance / variety regulated: assigned task uncertainty, local repository state, tool feedback, failures and peer change requests handled by each managed provider-backed actor. - Decisive decision or feedback right: choose substantive task-specific work in response to tool/environment observations and emit a structured result to the own team. - Decision owner: model-driven Claude/Codex/Copilot worker as a launched Team Agent seat; the vendor runtime supplies inference while Team Agent owns the composed operational role and result channel. - Supporting / enforcement mechanisms: compiled agent prompt, provider adapter, tmux transport, team spec, result envelope, task routing and durable state. - Closure path: user/leader assigns result-oriented work → first-party session launcher binds provider-backed worker and callable team tool context → autonomous worker chooses local task actions and receives environment feedback → reportresult returns work findings to the managed team. - Boundary reachability: documented standard team-agent wrapper, quick-start, spawnagents and reportresult are shipped installed paths rather than external operator scripts. - Why this is / is not agent-owned: without the instantiated model-powered specialist seat, Team Agent&#39;s transport/state cannot implement code itself. Credit is limited to the first-party composition, not provider-internal S2–S5, model performance or a standalone Rust coding loop. - Evidence: README.md; crates/team-agent/src/lifecycle/launch/spawn.rs; crates/team-agent/src/mcpserver/tools.rs; skills/team-agent/SKILL.md. - Basis: explicit installed launch and task/result structure; no witnessed live provider transcript. - Confidence: medium-high for reachability, not empirical work correctness. - Caveats: operation requires a compatible installed provider CLI and credentials; without these the Rust control plane cannot produce autonomous S1 work.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: construct a collision-safe physical/identity mapping for multiple managed S1 seat processes during restart and later message delivery. - Disturbance / variety regulated: stale restored team state can bind two distinct workers, or a worker and leader, to the same live pane/socket, directing later commands or messages to the wrong operational actor. - Decisive decision or feedback right: refuse reuse of an overlapping pane binding and force a new correctly owned worker seat instead of accepting stale &#39;already live&#39; inference. - Decision owner: deterministic first-party lifecycle collision/reconciliation path (constructor C); the model does not decide physical pane safety. - Supporting / enforcement mechanisms: paneconflictswithleaderorother, socket-sensitive pane identity, live-process checks, fresh-spawn fallback, scoped message-target resolution. - Closure path: restart inventory + persisted bindings → detect cross-seat pane ownership conflict → reject stale Noop reuse and start a distinct process → subsequent task messages/commands are applied to separately bound worker seats. - Boundary reachability: the collision check runs in the first-party startagent restart path, not just a fixture; it applies when resuming supported persistent teams. - Why this is / is not agent-owned: this is a deterministic first-party S2-specific interference attenuator rather than mere generic mailbox delivery or arbitration by a model. - Distinct S1 units: separate provider-backed specialist seats in the same Team Agent team, and the lead as a separately bound session. - Inter-S1 disturbance: the same pane process might be treated as owned by both teammates, leading to overlapping input and misattributed actions/results. - Attenuating coordination relation: exclusive socket-sensitive pane ownership plus fresh-spawn on detected conflicting binding. - Feedback into subsequent S1 behaviour: restored workers with invalid claimed panebindings are restarted/placed in their own pane; following work and messages target the corrected bindings. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: it directly prevents two operational actors from sharing a contested execution endpoint; it does not merely queue or address messages. - Evidence: crates/team-agent/src/lifecycle/restart/agent.rs; crates/team-agent/src/messaging/delivery.rs; crates/team-agent/src/topology.rs. - Basis: structural deployed restart code with a concrete collision condition and response. - Confidence: medium for supported protection; no live pane-collision trial. - Caveats: protects process/pane identity contention, not conflicting file edits across agents.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: model-led current team commitments and specialist assignment across multiple managed worker operations. - Disturbance / variety regulated: incomplete work, mismatched expertise, changing team capacity, needs for additional specialist seats and task/result coordination. - Decisive decision or feedback right: decide when to add a role, to whom to assign a task, what current status requires response and which current worker/leader message to send. - Decision owner: provider-backed managed leader agent when operating under the shipped Team Agent skill/MCP organization; the first-party Rust runtime executes commands but does not choose the team&#39;s changing work portfolio. - Supporting / enforcement mechanisms: team-status observation, role/spec compiler, team-scoped messaging and MCP, lifecycle add/restart/stop, durable task and result records. - Closure path: currently registered seats/status/results → leader model chooses team-wide intervention → Team Agent MCP/CLI checks identity/scope and applies add-agent / send / lifecycle change → new worker state and returned results become visible to the leader and follow-on worker decisions. - Boundary reachability: packaged skills/team-agent/SKILL.md is installed into provider skill locations; team-agent &lt;provider&gt; launches the leader, and MCP tools getteamstatus, sendmessage and addagent are backed by first-party runtime implementations. - Why this is / is not agent-owned: the leader can choose context-dependent changes in team capacity/commitments; status persistence and command validation alone would not pick the same changes. - Whole-system current view: scoped team roster/status, active workloads and results from registered teammates (not all external repositories/organizations). - Current-control decision scope: select/redirect task assignment and add/alter supervised execution capacity within the team rather than only performing its own local code action. - Evidence: README.md; skills/team-agent/SKILL.md; crates/team-agent/src/mcpserver/tools.rs; crates/team-agent/src/mcpserver/lifecycletools/statestatus.rs; crates/team-agent/src/lifecycle/launch/addagent.rs. - Basis: shipped model-led leader composition + executable team lifecycle; not a witnessed team run. - Confidence: medium; generic provider model behavior beyond the Team Agent-provided tool/right surface is not assumed. - Caveats: no distinct (P) mode is added merely because the user can also issue shell commands or instruct the leader; a separate parent-mode current-control closure would need its own evidence.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S3* / direct audit: - State: ? - Function: specialized independently tasked reviewer is supported as a configured teammate, but complementary direct artifact access, audit judgment and corrective binding return are not fully established as one shipped role/mode. - Disturbance / variety regulated: unsupported implementation claims and buggy patches returned by worker authors. - Decisive decision or feedback right: an independent reviewer must challenge producer claims with direct repo/test access and cause acceptance rejection or a returned corrective action, not just send an ordinary peer message. - Decision owner: potentially separately configured reviewer seat, but no shipped compulsory independent evidence or enforced rejection/recheck owner proven. - Supporting / enforcement mechanisms: teammate role compiler, peer messaging, independent provider sessions, custom role files, structured result envelopes. - Closure path: author reports output → optionally created reviewer may inspect it → messaging returns findings → whether that finding changes a binding work acceptance decision is unverified. - Boundary reachability: team-agent add-agent --role-file and examples document reviewers, but these are configurable compositions; the standard runtime does not itself establish an independent audit protocol from name alone. - Why this is / is not agent-owned: merely spawning a role called reviewer cannot prove separate access to raw operational reality or binding corrective closure. - Evidence: README.md; examples/team.spec.yaml; crates/team-agent/src/lifecycle/launch/addagent.rs; crates/team-agent/src/messaging/results.rs; crates/team-agent/src/mcpserver/tools.rs. - Basis: plausible shipped composition; function-specific independent closure remains uncertain. - Confidence: high in uncertainty, not a positive audited outcome. - Caveats: a deliberately built multi-agent reviewer loop might qualify on its own exact first-party composition evidence.\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no first-party environmental future intelligence that chooses an adaptation of Team Agent&#39;s future operational capability is established. - Disturbance / variety regulated: external changes in tools, roles, productivity constraints and future collaboration needs. - Decisive decision or feedback right: detect future-relevant external difference, create/adopt a prospective capability change and return it to current operating team. Not established. - Decision owner: user/developer can edit role files or reinstall tools, but no S4-specific first-party adaptation owner/closure is identified. - Supporting / enforcement mechanisms: durable team state, session restart/clone, role files, user-requested seat changes, stored results. - Closure path: messages and team state restore current work; no outside-and-then feedback loop changes future working capability through a distinct S4 decision. - Boundary reachability: the runtime supports persistence and role composition, not autonomous environmental scanning/adaptation in the standard packaged team. - Why this is / is not agent-owned: resuming agents or adjusting team count to satisfy today&#39;s request remains current operation/S3, not evidence of external-and-prospective S4. - Evidence: README.md; crates/team-agent/src/lifecycle/restart.rs; crates/team-agent/src/state/persist.rs; crates/team-agent/src/lifecycle/launch/addagent.rs. - Basis: source-first standard mode absence. - Confidence: medium-high under pinned reviewed boundary. - Caveats: an external provider&#39;s own learning or user-installed future-intelligence skill is not credited.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no decision-bearing ultimate identity/ethos/policy regulation beyond configured team identity/permissions has been evidenced. - Disturbance / variety regulated: durable team mandate and ultimate goal/policy conflicts, distinct from authentication/role mapping. - Decisive decision or feedback right: choose ultimate mission/policy and return it to govern subsequent team operation; not demonstrated. - Decision owner: operator defines initial objective, team spec and role constraints; Rust runtime checks scoped identity/permissions but does not own ultimate policy judgment. - Supporting / enforcement mechanisms: named team/owner key, team membership, captured MCP identity, agent-role configuration, lifecycle safety and permission flags. - Closure path: initial human-defined team spec → binding launch/config scopes; no specific ultimate-policy dispute → legitimate parent decision → applied policy return cycle is established. - Boundary reachability: identity and permission checks are first-party runtime paths but are insufficient for positive S5. - Why this is / is not agent-owned: stable identity keys, enforced permissions and leadership role labels are mechanisms, not a legitimate identity-level ultimate policy decision organ. - Evidence: crates/team-agent/src/lifecycle/launch/identity.rs; crates/team-agent/src/mcpserver/tools.rs; skills/team-agent/SKILL.md; examples/team.spec.yaml. - Basis: structural bounded negative search under supported modes. - Confidence: medium-high for pinned standard distribution. - Caveats: a human operator may hold S5 for a wider project/institution; such authority is not automatically a first-party team-level P closure.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/0b56a74b79f008576dbd617d9100c3ec73856488/assessments/team-agent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 0b56a74b79f008576dbd617d9100c3ec73856488\">0b56a74 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-10-19T20:48:13+03:00\"><th scope=\"row\"><a href=\"https://github.com/liliang-cn/harness-rs\" target=\"_blank\" rel=\"noopener\">Harness RS</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-19\">2026-10-19</time></td><td class=\"review-ref\"><a href=\"https://github.com/liliang-cn/harness-rs/tree/eb26e73fa4ca3e581e8e61be7a6c9bb91bd5f329\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision eb26e73fa4ca3e581e8e61be7a6c9bb91bd5f329\">eb26e73 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Choose and execute context-dependent steps, tools and responses for task completion using observed action feedback. - Disturbance / variety regulated: Heterogeneous user tasks, tool outcomes, changed workspace state, execution errors, failed acceptance and context-size pressure. - Decisive decision or feedback right: The configured Model behind AgentLoop selects tool names/arguments or final output based on current context and returned tool/sensor/acceptance feedback; shell/file/web tool grants are caller-specified. - Decision owner: Model-backed agent in first-party packaged AgentLoop::run and tool registry wiring; not a test MockModel, hook veto or external business operator. - Supporting / enforcement mechanisms: Guides, typed Tool schemas, Model adapters, PreToolUse/PostToolUse hooks, sensors, Acceptance checks, Policy and budget guards, context compaction and response receipts. - Closure path: User task → context + guides + tool schemas → model completion/stream → chosen authorized tool executes → tool result/sensor observation/acceptance result → next model decision or terminal outcome. - Boundary reachability: AgentLoop::new(model) and public run call runbuiltcontext → runinspan with concrete model calls and typed tool dispatch, instrumented feedback after execution and return to the same loop; README demonstrates this actual supported Rust runtime rather than an adjacent benchmark runner. - Why this is / is not agent-owned: Without the model, policy/hook infrastructure still checks and records work but cannot select a context-dependent tool/answer based on observed results. The model holds the material operational discretion. - Evidence: README.md#L35, crates/harness-loop/src/lib.rs#L647, crates/harness-loop/src/lib.rs#L1008, crates/harness-loop/src/lib.rs#L1561, crates/harness-loop/src/lib.rs#L1793, crates/harness-loop/src/lib.rs#L2215. - Basis: Explicit first-party model/tool composition and feedback, without live remote model benchmark evidence. - Confidence: High for structural support. - Caveats: Runtime execution and hosted model response were not verified in the available Linux environment.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No separate first-party regulator of actual interference between independently viable S1 divisions, returning changed commitments/operations to the conflicting units, is proven at this assessed operating-cell boundary. - Disturbance / variety regulated: Child task dependencies, concurrent tool calls, scheduling and potential workspace contention are plausible but generic task dispatch and orchestration do not establish a concrete inter-S1 conflict/oscillation relation. - Decisive decision or feedback right: The user/developer configures DAG job dependencies, task routing or registered tools; runtime enforces a chosen execution plan. There is no evidenced agent-owned S2 interference adjudication across autonomous sibling S1 operational domains. - Decision owner: Application constructor, current task model or deterministic orchestration scheduler, not a distinct S2 function. - Supporting / enforcement mechanisms: Subagent API, Orchestrator, scheduler jobs, HookBus, tool concurrency and task result handling. - Closure path: Parent/current task delegates → child executes → returned result or error → parent continues; there is no concrete S1 conflict sensed → S2 decides dampening → revised independent S1 behavior relationship. - Why this is / is not agent-owned: A task dispatcher executes choices at the S1/task layer and can synchronize tools, but neither scheduling nor shared transport supplies an evidenced viable-operating-division coordination right. - Evidence: crates/harness-loop/src/subagent.rs#L92, crates/harness-loop/src/orchestrator/orchestrator.rs#L101, crates/harness-loop/src/scheduler/scheduler.rs#L1. - Basis: Bounded negative for the shipped single-agent plus optional subagent operating modes. - Confidence: Medium-high. - Caveats: A downstream application could compose independent agents and provide S2, but its inter-S1 governance is outside the packaged boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No discretionary first-party whole-current portfolio manager owns negotiated priority, resource or obligation adjustments across independently viable S1 divisions. - Disturbance / variety regulated: Token budgets, stuck tool loops, commands, approval levels and resource exhaustion can threaten local execution, but they are run-level constraints and immediate controls. - Decisive decision or feedback right: Developer/host chooses Policy (L1/L2/L3 operating constraints), Hooks, budgets and acceptance criteria; the AgentLoop applies deterministic bounds and model acts within them. - Decision owner: User/application for resource/policy configuration; deterministic runtime enforces per-run limits; model acts in S1. - Supporting / enforcement mechanisms: Runtime policy, bounds and loop engine, acceptance checks, human gate hooks, cancellation, stuck/monotony detectors, recorder/telemetry. - Closure path: Tool call or budget event → configured guard denies/corrects/halts one task → same operating loop continues/stops. No portfolio managerial decision/return across autonomous S1 organizations. - Why this is / is not agent-owned: Earned L1/L2/L3 approval is a harness security/autonomy deployment setting, not VSM S3 by numeric name or an evidence of autonomous enterprise-manager authority. - Evidence: README.md#L15, crates/harness-loop/src/lib.rs#L698, crates/harness-loop/src/lib.rs#L1446, crates/harness-loop/src/acceptance.rs#L1, crates/harness-loop/src/loopengine/mod.rs#L1. - Basis: Bounded source-negative in packaged configuration and operational management paths. - Confidence: Medium-high. - Caveats: Human/application may provide actual S3 outside this assessed first-party recursion.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No operational independent complementary reality-inspection path with a mandate to correct a separate S3 managerial picture and cause subsequent present-regulation adjustments is shown. - Disturbance / variety regulated: Incorrect outputs, failed tools and unaudited actions are observable; sensors, acceptance and AuditHook can test/log single-run events but do not establish independent audit correction of a first-party S3. - Decisive decision or feedback right: Registered sensors/acceptance criteria and configured AuditHook record or locally veto actions; no audit officer/agent with independent organizational S3 corrective mandate. - Decision owner: Task-time validators/host-defined hooks, not a separate complementary audit function. - Supporting / enforcement mechanisms: AuditHook, tracing/telemetry, Acceptance, Sensor, run receipts and replay recorder. - Closure path: Action → hook or local validation → same task accepts/retries/logs; no alternative independent operational inspection → S3 misinformation corrected → S3 changes current organizational management. - Why this is / is not agent-owned: Telemetry and validators may provide evidence useful to an auditor, but are not themselves separate audit rights that can change present S3 decisions. - Evidence: README.md#L90, crates/harness-loop/src/lib.rs#L1634, crates/harness-loop/src/lib.rs#L1894, crates/harness-loop/src/hooks/mod.rs#L1. - Basis: Bounded negative after examining audit, sensors and external review. - Confidence: Medium-high. - Caveats: Independent human audit could be layered by a downstream host.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Disturbance / variety regulated: Future task diversity, recurrence of complex procedures, changing tool affordances and the need to preserve a generalized successful multi-step approach for later agent tasks. - Function: Form a generalized future operating skill from successful past complex tasks and make it persistently available for later task capabilities in an explicitly selected supported operating mode. - External distinction: ExperienceRecorder/episode tool traces expose actual task context, tools used and outcome; SkillDistiller::gate checks success, diverse tools, situation length and duplicate-skill similarity against existing loaded skills. - Future / prospective distinction: The model-backed distillation prompt directs the model to generalize the successful episode into an agentskills.io-compatible procedure for a future class of tasks, not to solve the same current task again. - Adaptation option generated: A model produces a named reusable SkillDraft with instructions; the first-party validator checks schema/lint/duplicate safety. - Path back into current capability / S3: In explicitly documented, first-party opt-in distillandwrite(ep, skillsroot) mode, the accepted draft is written under &lt;skillsroot&gt;/&lt;name&gt;/SKILL.md using the same first-party harness-context skills-root format. Subsequent operating sessions explicitly configured to scan/use that skills root can make the new procedure available to model task solving. Return is to future S1 capability, not a claimed separate S3 executive; no default automatic invocation. - Decisive decision or feedback right: The model selects prospective generalized procedural content; the selected DistillPolicy is deterministic, and the host selects the invocation and whether to enable automatic writing versus requiring review. The source-backed autonomous portion is the model&#39;s future procedural option, integrated into a documented auto-write first-party mode. - Decision owner: Configured model through shipped SkillDistiller after opt-in; application owner chooses when to call and provides skills directory. Draft-only default multi-tenant branch remains parent/host-reviewed and does not create autonomous admission. - Supporting / enforcement mechanisms: Episode recorder/guide, policy gate, skill validation, duplicate scan, SkillDraft::writeto, harness-context skills-root scanner, optional skillmanage tool and skill loader. - Closure path: Successful multi-step environmental episode → model generalizes prospective skill → safety and duplicate checks → opt-in write to canonical skill path → skills root available to configured later AgentLoop use → new goal encounters improved procedure. - Boundary reachability: SkillDistiller::new(model), public distillandwrite and first-party SkillDraft::writeto are exported, tested and documented for a host that opts out of approval; the docs explicitly distinguish review-only distill() and packaged automatic persistence. harness-context::skills/harness-tools implement scan/management of the persisted SKILL.md format. This is not an external user custom tool invented for the assessment. - Why this is / is not agent-owned: Remove the model and the first-party policy/recorders retain successful episodes but cannot propose the generalized future procedure. Optional host invocation does not mean automatic background strategic intelligence is present. - Evidence: crates/harness-loop/src/experience/mod.rs#L20, crates/harness-loop/src/experience/mod.rs#L54, crates/harness-loop/src/experience/distill.rs#L1, crates/harness-loop/src/experience/distill.rs#L259, crates/harness-loop/src/experience/distill.rs#L367, crates/harness-loop/src/experience/distill.rs#L416, crates/harness-loop/src/experience/distill.rs#L873, crates/harness-tools/src/skills.rs#L1. - Basis: Source-connected opt-in first-party autonomous future skill synthesis with persistent output, not claim of default auto-learning or measured improvement. - Confidence: Medium for supported optional mode; no provider live task run was independently executed. - Caveats: The host must initiate distillation and configure later skill loading; the commonly recommended multi-tenant mode holds the draft for parent/human review. No autonomous reconfiguration of Policy, S5 or all future services is claimed.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No first-party legitimate ultimate-identity authority adjudicates conflicting organizational purposes with binding long-term returned policy for this single-agent organization. - Disturbance / variety regulated: Risks from untrusted shell/tools, filesystem scope and skill modifications motivate guardrails and human approvals; no organizational identity conflict decision protocol is shipped. - Decisive decision or feedback right: Application/user configures model policy, allowlists, sandbox and human approvals; runtime enforces selected bounds but does not decide ultimate organization mission. - Decision owner: External user/application owner and deterministic policy guard; not a model-based constitutional authority. - Supporting / enforcement mechanisms: Hooks, approval gates, sandbox, Policy levels, skill lint/validation, audit logs. - Closure path: Configured action → allow/deny/approval enforcement → current task proceeds/halts; no ultimate-purpose issue reaches legitimate S5 and returns a durable constitutional decision. - Why this is / is not agent-owned: Security and operator consent mechanisms are not organizational policy ownership simply because labelled Policy, Audit or L1–L3. - Evidence: README.md#L25, crates/harness-loop/src/lib.rs#L1793, crates/harness-loop/src/experience/mod.rs#L54, crates/harness-loop/src/loopengine/mod.rs#L1. - Basis: Bounded negative for standard distribution and opt-in skill-learning mode. - Confidence: Medium-high. - Caveats: Actual human governance and higher-recursion organization are external and should be assessed separately.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/d701ec67c96e39de5971271f6158997337c6e524/assessments/ha/harness-rs.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit d701ec67c96e39de5971271f6158997337c6e524\">d701ec6 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-10-14T17:09:33+03:00\"><th scope=\"row\"><a href=\"https://github.com/WrongStack/WrongStack\" target=\"_blank\" rel=\"noopener\">WrongStack</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-14\">2026-10-14</time></td><td class=\"review-ref\"><a href=\"https://github.com/WrongStack/WrongStack/tree/42d410f938ba644e70771e200f39903117507a72\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 42d410f938ba644e70771e200f39903117507a72\">42d410f &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: transform uncertain software-development tasks into model-chosen file edits, tool commands and feedback-driven corrections. - Disturbance / variety regulated: changing codebase, errors, tests, provider output, tool feedback and task constraints. - Decisive decision or feedback right: select task-relevant coding tools, delegate bounded work and alter next actions on returned observations. - Decision owner: WrongStack&#39;s first-party model-directed worker and optional role subagents; external inference serves the first-party loop. - Supporting / enforcement mechanisms: tool executor, provider transports, permission gates, session/context/memory stores, tool outcome events, kernel run controller. - Closure path: model receives task+workspace evidence → chooses tool/arguments → first-party execution → real result returned into conversation → revised model coding choice or outcome. - Boundary reachability: shipped CLI/desktop/web agent sessions instantiate the first-party loop and tools without launching a different coding-agent CLI. Fleet mode spawns additional first-party model runners. - Why this is / is not agent-owned: removing model-directed tool choices while leaving runtime/permissions yields no equivalent adaptive task execution. - Evidence: README.md; packages/core/src/core/agent-loop.ts; packages/runtime/src/host.ts; packages/core/src/coordination/director.ts; packages/cli/src/fleet/host-subagent-factory.ts. - Basis: explicit + structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate interference when distinct mutating first-party S1 workers produce overlapping changes for the same coding project. - Disturbance / variety regulated: conflicting edits and commits from concurrent independent coding tasks, risking overwrites/invalid integration. - Decisive decision or feedback right: a shipped worktree constructor isolates a child to its own branch and admits or rejects subsequent integration on real three-way merge conflict evidence. Its conflict/commit result enters the originating task&#39;s status and parent task handling; optional resolver may select a repair, but this is not credited to the deterministic constructor. - Decision owner: first-party runtime WorktreeTaskRunner/WorktreeManager constructor for isolation, merge admission, conflict detection and returned failure/status; human/model authority over how to repair remains distinct. - Supporting / enforcement mechanisms: git worktrees/branches, commitAll, merge --squash, index/conflict-marker checks, WorktreeIntegrationError and task/worktree state registry. - Closure path: competing child changes → isolated branches → guarded merge → either integrated accepted result or path-specific conflict/failure returned into task state/parent observation → next work can be revised or withheld rather than silently committed. - Boundary reachability: Director wires wrapSubagentRunnerWithWorktrees with the WorktreeManager constructed by shipped MultiAgentHost in the supported enabled worktree policy; this is more than a library method waiting for downstream implementers. - Why this is / is not agent-owned: the S2 anti-interference function is real, but the isolation/merge/conflict-return rule remains deterministic even with the model actor removed; therefore constructor C, not A. - Distinct S1 units: separately model-running coding subagents attached to a Director session and independently modifying their assigned worktrees. - Inter-S1 disturbance: same-path/same-project changes that cannot be safely combined after parallel worker work. - Attenuating coordination relation: per-subagent checkout isolation and serialized git merge admission with conflict-file detection. - Feedback into subsequent S1 behaviour: failed integration returns a structured WorktreeIntegrationError and task conflict status with specific files to parent/Director rather than exporting an undetected conflicting combined edit. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the control specifically guards actual conflicting outputs of different S1 workers at the shared integration point, and provides conflict-specific regulation/return rather than just sequencing task dispatch. - Evidence: packages/core/src/coordination/worktree-task-runner.ts; packages/core/src/worktree/worktree-manager.ts; packages/core/src/coordination/director.ts; packages/cli/src/fleet/host-director-builder.ts. - Basis: structural + explicit - Confidence: medium-high - Caveats: optional worktrees may be off or fall back in some configurations. The positive C state is bounded to the supported worktree-enabled multi-worker mode. No evidence of autonomous inter-worker bargaining is claimed.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: control current commitments, assignments and capacity of the running role-agent fleet, not merely a worker&#39;s own task schedule. - Disturbance / variety regulated: unbalanced workload, stuck/erroring workers, stale commitments, idle helpers, constrained parallel capacity and non-progressing work. - Decisive decision or feedback right: the model-directed leader/Director chooses task delegation and reassignments from task/fleet state; the optionally enabled supervisor further proposes operational interventions and asks Brain (policy/LLM/human tier) before retargeting unstarted work or steering a worker. - Decision owner: model-directed first-party Director lead for discretionary whole-fleet current decisions in the supported fleet mode; Brain/model/human tier ownership is recorded separately for supervisor interventions, rather than assuming a deterministic watchdog always owns the decision. - Supporting / enforcement mechanisms: FleetManager, DirectorTaskRegistry, FleetBus, task results, budget rules, FleetSupervisor, engageRebalance, roster status and terminal/remote fleet controls. - Closure path: live worker/queue/commitment state → leader model task/agent decision (or optional Brain-adjudicated supervisor proposal) → assigned/retargeted/steered/terminated worker → updated per-task and fleet status for subsequent management turns. - Boundary reachability: shipped MultiAgentHost instantiates Director/FleetManager; Director exposes spawn, assign, status, retarget and terminate functions to active agent sessions. FleetSupervisor is a wired optional supervisory mode, not a documentation-only wishlist. - Why this is / is not agent-owned: removing the model-directed leader from Director mode removes its discretionary prioritization and reassignment choices; deterministic roster bookkeeping, hard spawn caps and timeout monitors remain supporting tools. Automated Brain policy enforcement alone is not the positive A basis. - Whole-system current view: the current project-fleet roster, task registry, pending/completed work, running/idle subagents, outcomes and budget/usage within the declared Director session. - Current-control decision scope: discretionary current task assignment and reallocation to workers, worker steering/termination, response to stuck status and live capacity selection. - Evidence: packages/core/src/coordination/director.ts; packages/core/src/coordination/director/director-task-registry.ts; packages/core/src/coordination/fleet-supervisor.ts; packages/core/src/coordination/fleet-supervisor-rebalance.ts; packages/cli/src/fleet/host-director-builder.ts; packages/cli/src/fleet/host-supervisor.ts. - Basis: explicit + structural - Confidence: medium-high - Caveats: this S3=A is for actual first-party Fleet/Director model mode, not merely the single-agent REPL or all UI dashboards. A separate parent-governed S3 path has not been positively established here; no speculative (P) is attached.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S3* / direct audit: - State: ? - Function: independently challenge claims about changed code/task completion and return evidenced findings to operational control. - Disturbance / variety regulated: incorrect patches, test regressions, non-factual claims of successful completion and unverified acceptance criteria. - Claim being audited: model-worker implementation success / code quality / changed-file defect freedom. - Ordinary reporting path: authoring worker&#39;s own tool/test output, task result and session/Director reporting. - Complementary access path: Chimera independently instantiated model reviewer with separate read-only permissions, real source/diff evidence and on-disk citation verification; Kanban verification gate also examines executable acceptance checks. - Independence boundary: reviewer has separate model runner and constrained direct-file evidence access; deterministic Kanban test execution is distinct from a worker&#39;s prose. Material independent decision and closure across these mechanisms remains unresolved. - Who acts on findings: Chimera report is persisted and delivered via project mailbox; code explicitly says the default delivery is informational and does not automatically start a leader turn, fixer or cascade. Kanban gate can reject or park a managed task, but its relationship to complementary supervisory correction needs the full configured mode traced. - Decisive decision or feedback right: reviewer model owns code critique; gate owns test verdict; downstream authoritative corrective dispatch cannot be established from those facts alone at the stated boundary. - Decision owner: model auditor for Chimera critique, deterministic verifier for Kanban evidence, and optional leader/human for subsequent action; final composite S3 ownership unresolved. - Supporting / enforcement mechanisms: chimera.reviewneeded event, read-only reviewer policy, citation-to-disk validation, mailbox and report stores, finalizeTaskCompletion and managed-board completion checks. - Closure path: independent inspection → report/verdict → mailbox or completion-gate status; whether findings cause closed corrective management action in a supported first-party mode is not yet evidenced. - Why this is / is not agent-owned: model-backed challenger exists and may be genuinely complementary, but independence of inspection alone is not the complete S3 correction function, especially where normal review explicitly avoids automatic reentry. - Evidence: packages/cli/src/execution-chimera-review.ts; packages/cli/src/chimera-reviewer-policy.ts; packages/cli/src/execution-chimera-cascade.ts; packages/kanban/src/verification/completion-gate.ts; packages/kanban/src/verification/completion-protocol.ts. - Basis: structural + unresolved - Confidence: medium - Caveats: ? identifies a concrete first-party reviewer/gate return ambiguity, not a missing reviewer component. Do not promote to A or C without closing the outcome→remediation path or proving the independent gate itself closes complementary audit at the correct recursion.\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S4 / adaptation: - State: ? - Function: transform project-environment feedback and past role failures/successes into prospective changes in the agent organization&#39;s future practice/capability. - Disturbance / variety regulated: recurring defects and changing project conventions/tool competence that might require a new role-specific rule or reusable skill. - External distinction: project/task outcomes, repo-specific observations and applied directive success rates are captured outside the immediate internal prompt-generation logic. - Future / prospective distinction: auto-optimization selects and refines reusable role instructions/addenda for later work, not merely the current tool call. - Adaptation option generated: model-driven consolidation of past directives with applied/win statistics and generated skill-specific addenda. - Path back into current capability / S3: serialized guidance is reloaded by subsequent role-agent context building; however whether this closes the full outside-and-then organizational S4 loop rather than internal experience distillation is not resolved. - Decisive decision or feedback right: auto-optimization scheduler deterministically selects when to run; model optimizer can synthesize the material practice, but classification of the environmentally prospective organizational decision remains unproven. - Decision owner: first-party model optimizer for consolidation; runtime for scheduling and persistence; possible S4 decisive owner unresolved. - Supporting / enforcement mechanisms: learned directive capture and grades, optimization thresholds, LearningOptimizationScheduler, persisted consolidated documents and skill addenda, project-aware skill retrieval. - Closure path: scored completed task observations → scheduled optimization/model synthesis → persistent project-role skill addendum → subsequent specialist context; remaining gap is proving that this is a VSM S4 external-future adaptive control decision rather than routine local retrospective learning. - Why this is / is not agent-owned: real model-dependent future-guidance synthesis exists, so a bounded no-path — is premature; whether it meets the complete S4 functional relation must be separated from positive S1 memory. - Evidence: packages/cli/src/fleet/host-learning.ts; packages/cli/src/fleet/host-learning-scheduler.ts; packages/core/src/coordination/agents/project-agent-auto-optimize.ts; packages/core/src/coordination/agents/project-agent-optimizer.ts; packages/cli/src/fleet/host-context.ts. - Basis: structural + unresolved - Confidence: medium - Caveats: ? is not a claim that any memory or self-improvement feature is automatically S4. The specific future-role-guidance path is implemented, but its organizational/outside-future decision boundary is unsettled.\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party identity/ultimate-purpose dispute → legitimate authority → returned authoritative organizational policy loop established for this installed coding organization. - Disturbance / variety regulated: risky tool calls, unauthorized paths, changes to team constraints, human-required operations and project governance rules are possible policy enforcement inputs. - Decisive decision or feedback right: the operator/developer configures an autonomy envelope and project permissions; governance/Brain decides or escalates individual risk-tier operations, not a demonstrated authoritative decision over ultimate organizational identity/purpose. - Decision owner: operator/config for permission ceilings and project-authored goals; policy/Brain layers for task/action authorization, but no owner identified for a first-party identity-level S5 function. - Supporting / enforcement mechanisms: governance AutonomyEnvelope, rule/permission policy, Brain approval/escalation, path gates, capability grants and project task contracts. - Closure path: a permission decision returns to authorize/reject a tool or task; no supported ultimate identity/policy issue → legitimate S5 authority → durable returned rule changing the organizational purpose/governing identity has been traced. - Why this is / is not agent-owned: the presence of autonomous approval decisions does not make the Brain an ultimate-policy owner; removing the Brain leaves higher-level operator-defined risk limits and project identity settings. - Evidence: packages/governance/src/autonomy-envelope.ts; packages/governance/src/task-contract.ts; packages/governance/src/project-service.ts; packages/core/src/coordination/brain.ts; packages/core/src/security/permission-policy.ts; README.md. - Basis: explicit + structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/b8250718a4985f1a86ddc6d827de42134cf133bf/assessments/wrongstack.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit b8250718a4985f1a86ddc6d827de42134cf133bf\">b825071 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-10-18T18:34:28Z\"><th scope=\"row\"><a href=\"https://github.com/ramannanda9/agent-harness\" target=\"_blank\" rel=\"noopener\">react-agent-harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-18\">2026-10-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/ramannanda9/agent-harness/tree/6b399e57daeef6475f2dc37c11a1e8fc097ca7e4\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 6b399e57daeef6475f2dc37c11a1e8fc097ca7e4\">6b399e5 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Produce task-specific technical, research or tool-using outcomes through distinct model-backed ReAct specialists. - Disturbance / variety regulated: Variable task intent, uncertain tool outputs, investigation and local implementation decisions under dynamically observed results. - Decisive decision or feedback right: Select next thought, tool invocation, arguments and final answer in each agent&#39;s permitted domain. - Decision owner: A supplied LLM acting through first-party BaseAgent and registered AgentConfig. Tool registry and human allow gates bound the choices but do not select the answer. - Supporting / enforcement mechanisms: AgentConfig, allowlisted ToolRegistry, ReAct loop, working memory, streaming bus, per-run budget and error/resume state. - Closure path: User goal → router or orchestrator chooses task → BaseAgent interprets observation and chooses action/tool → actual tool result returns to its reasoning loop → agent returns concrete task output for the parent run. - Boundary reachability: The shipped AgentRuntime instantiates BaseAgent for registered configurations in both direct and orchestrated entry points; examples exercise a deterministic provider stub without adding outside orchestration code. - Why this is / is not agent-owned: A model chooses substantive next actions conditional on tool output; the framework configures boundaries but does not deterministically decide task substance. - Evidence: Agent configuration, Agent ReAct phases, tool execution, runtime run paths. - Basis: Source-explicit model-driven ReAct, structurally reachable through public runtime. - Confidence: High structurally; no production-model observations at this frozen ref. - Caveats: The example MockLLM only validates wiring and should not be mistaken for model quality or externally authorized tool execution.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: Attenuate concrete interference when multiple S1 task runs use one shared registered agent template and would overwrite each other&#39;s local task and working-memory state. - Disturbance / variety regulated: Two concurrent task drivers receiving identical/incorrect answers after the second overwrites the first task&#39;s mutable BaseAgent instance; nested stateful delegation can reproduce that corruption. - Decisive decision or feedback right: Allocate an independent mutable runtime state to each ready task, including per-run steering, working memory, checkpoint scope and stateful nested subagent tool, while preserving a shared run-wide budget. - Decision owner: Deterministic first-party Orchestrator and BaseAgent cloneforrun machinery; no autonomous agent negotiates the two task runs&#39; shared-resource conflict. - Supporting / enforcement mechanisms: Clone-per-task, separate stateful child tools, task-scoped checkpoints, isolated steering queues, common budget and fan-in result collection. - Closure path: DAG produces simultaneous ready tasks referring to the same registered agent → executor clones per task before launch → independent instruction/memory/action execution → distinct valid outputs returned for the corresponding tasks; later planner branches on each separate result instead of overwritten shared state. - Boundary reachability: Orchestrator.runbatch invokes cloneforrun for each Task in the normal shipped parallel code path. A first-party explicit regression test exercises genuine asyncio interleaving and asserts distinct returned answers and original registry preservation. - Why this is / is not agent-owned: Specific inter-S1 destructive interference is remedied by a shipped deterministic constructor/enforcement path. A planner&#39;s LLM makes assignments, but does not make the isolation decision or handle competing resource claims. The optional LLM memory reconciler concerns later semantic persistence and must not be borrowed as agent-owned live coordination between these task actors. - Distinct S1 units: Concurrent tA and tB operational task runs (even if they share one agent template ID); each has a distinct task, working state and outcome. - Inter-S1 disturbance: Actual structurally demonstrated shared-instance overwrite causing both task actors to report the second task&#39;s answer while falsely succeeding. - Attenuating coordination relation: Require a unique clone of BaseAgent and stateful tools for each task within the fan-in batch, isolate checkpoint and steering scopes. - Feedback into subsequent S1 behaviour: Each task retains and executes its own instruction, returns a separate output, and downstream dependent tasks/planner use the correct per-task result. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: This directly prevents a demonstrated cross-worker mutable-state collision at the shared instance boundary, not merely ordering a DAG or carrying messages. - Evidence: Concurrent collision regression, nested tool and budget controls, cloneforrun, Orchestrator.runbatch. - Basis: Explicit concrete failure class plus first-party executable mitigation, with structural test coverage. - Confidence: High for the narrow interference class; no evidence of general inter-worker negotiation/portfolio resource fairness. - Caveats: C is not independent autonomous S2 decision rights; other cross-agent conflicts (external tools, shared database, contradictory facts) are not universally resolved by per-agent copies.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: Regulate current whole-run multiagent commitments by choosing and revising which specialist tasks are to proceed, retry, skip or be replaced when observed results fail. - Disturbance / variety regulated: Failed/low-confidence S1 results, current goal incompleteness, a DAG no longer suitable for the remaining workload and finite run budget. - Decisive decision or feedback right: Choose new task assignments, instructions and dependency/remaining-work configuration in a fresh DAG following failures or low-confidence results. - Decision owner: Model-backed run-level planner/replanner LLM in the shipped Orchestrator; fixed onfailure, max-replan count, validator and BudgetGuard only enforce constraints and trigger thresholds. - Supporting / enforcement mechanisms: TaskResult/evaluation, validated DAG, shared budget, run-state/checkpoints, task statuses, streaming feedback and run-level model prompt. - Closure path: Whole-run task/result overview → low-confidence/error and remaining DAG → model chooses revised tasks/agents → validated new DAG replaces current pending commitments and checkpoints → changed S1 agents/tasks actually execute next → synthesized whole-goal answer. - Boundary reachability: AgentRuntime.buildorchestrator directly wires plannerllm and actual registered agents. executeplanstream calls replan on in-boundary task failures and replaces pending tasks with the returned validated plan. - Why this is / is not agent-owned: Removing the planner LLM removes the discretionary reassignment/revision of remaining run-wide commitments; remaining deterministic scheduler and budget checks can enforce and retry/abort but cannot choose the new goal-specific DAG. - Whole-system current view: Run goal, full selected specialist registry, existing completed and failed task results, and remaining unfinished tasks carried in the replan prompt. - Current-control decision scope: Task commitment/agent assignment and revision of remaining present work, not merely initial decomposition; no evidence of organization-wide staffing/portfolio/budget policy beyond this one-run recursion. - Evidence: Runtime orchestrator wiring, Run-plan ownership, Failure/replan control and pending replacement, LLM plan and replan. - Basis: Explicit live feedback/reallocation path with autonomous model judgment. - Confidence: Medium-high structural, restricted to current goal execution. - Caveats: Only low-confidence/failure triggers drive replanning; decision is bounded by max-replan and registered agents, and real external-provider efficiency/correctness is unmeasured. Opt-in PersistentAgent plan-mode lets a human approve/revise an ordinary step plan, but primarily returns prompt priors, not a separate authoritative whole-system parent current-control loop at this assessed recursion; no S3 (P) modifier is claimed. Plan-mode prior injection.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: Independent complementary access to operational truth beyond agents&#39; normal self-reported outcomes, with audit findings returned to present control. - Disturbance / variety regulated: Potential fabricated tool outcomes or an overconfident producer report that ordinary run traces/quality signals would fail to challenge. - Decisive decision or feedback right: No distinct first-party independently empowered raw-evidence auditor established in this boundary. - Decision owner: Not established; production specialists and orchestrator are ordinary operational actors, while an optional human plan approver reviews future plan proposal rather than actual independent evidence. - Supporting / enforcement mechanisms: Trace/event capture, model response confidence, task validation, HITL tool approval and plan-mode prompts; these are not independent complementary audit owners. - Closure path: No first-party independent evidence acquisition → autonomous auditor verdict → corrective S3 intervention loop shown. - Why this is / is not agent-owned: The synthesized answer and conflict list are derived from producer TaskResult rather than independently inspecting task-primary artifacts; no separate read-only reviewer/remediation control is mandated. - Evidence: Synthesis prompt, synthesis after ordinary task results, approval gate, trace and run events. - Basis: Bounded absence after inspecting shipped orchestration, synthesis, audit-like tracing and HITL. - Confidence: Medium-high for the first-party standard paths. - Caveats: Developers can register a separate auditor as an ordinary specialist, but no shipped independent review contract plus corrective return exists automatically.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: Externally oriented prospective assessment and option generation to change future system capability, returned to current S3. - Disturbance / variety regulated: Changes in future user demands, models, tools or environment that would require a prospective capability/organization redesign. - Decisive decision or feedback right: No first-party prospective option right and adoption loop established. Model selection, memory consolidation and replanning change current task execution, not future operational capability. - Decision owner: Not established in the shipped reviewed modes. - Supporting / enforcement mechanisms: RoutingLLM and ModelSwitcher for configured choices, run-end memory reconciliation, failure replanning, session persistence, background task tools and extensibility hooks. - Closure path: No shipped external/future model → capability-change option → commitment/adoption into present runtime or S3. - Why this is / is not agent-owned: Config-driven model changes and retrospective context writing are not agent-judged external strategic adaptation with installed capability consequences. - Evidence: Routing, manual model switching, Replan prompt only current work, reconciliation for future memory. - Basis: Bounded negative from complete reviewed prospective-looking surfaces. - Confidence: Medium-high within the shipped execution cell. - Caveats: The adopter can write custom forecasting/adaptation agents, but the repository does not ship their specific function/authority loop.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: Legitimate purpose/identity and ultimate organizational-policy choice balancing current execution and prospective adaptation. - Disturbance / variety regulated: Ultimate conflict over the goal cell&#39;s persistent mission, acceptable mission changes or constitutional boundary at the organizational recursion. - Decisive decision or feedback right: No source-owned identity-level ultimate-policy decision owner or escalation/return mechanism. - Decision owner: Not established. AgentConfig prompts and allowed tools are adopter inputs; HITL and approval gates cover task/plan/action permission, not authoritative identity revision. - Supporting / enforcement mechanisms: Static role/system prompts, tool policy allow lists, explicit human tool/plan approvals, guardrail values, persistent session configuration. - Closure path: No first-party path from identity-level question to legitimate ultimate authority and returned binding new mission policy. - Why this is / is not agent-owned: A system prompt or safety constraint bounds tasks without constituting a live identity government. Ordinary operator approval is not an identity-level arbitration loop. - Evidence: AgentConfig, tool policy, HITL, plan-mode approval. - Basis: Bounded negative after examining all shipped policy-like/approval surfaces. - Confidence: High for the declared execution-cell boundary. - Caveats: An adopter may establish institutional parent S5 outside this library; absent a first-party identity/ultimate-policy return path it cannot be borrowed here.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/e86763818d44cb805c4d122b32ce8cfb20ae9def/assessments/re/react-agent-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit e86763818d44cb805c4d122b32ce8cfb20ae9def\">e867638 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-10-11T22:06:48+03:00\"><th scope=\"row\"><a href=\"https://github.com/Aliivihu786/astro-code\" target=\"_blank\" rel=\"noopener\">Astro Code</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-11\">2026-10-11</time></td><td class=\"review-ref\"><a href=\"https://github.com/Aliivihu786/astro-code/tree/5aae2bddfc364bc492a8cae509b20eb94455560c\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 5aae2bddfc364bc492a8cae509b20eb94455560c\">5aae2bd &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously execute delegated software investigation and edits against a changing working tree, including when a teammate executes an assigned operational subtask. - Disturbance / variety regulated: user requests, tool outcomes, repository state, dependency failures, findings from other teammates and task status changes. - Decisive decision or feedback right: model-selected tool action and next step after actual tool/agent result, independent of the fixed runtime machinery that invokes tools. - Decision owner: first-party Astro Code session model, or a spawned teammate&#39;s model in enabled team mode, acting through Astro-provided execution loops. - Supporting / enforcement mechanisms: prompt context, query engine, SDK/provider client, tool registry, permissions, task file persistence, communication and run-state UI. - Closure path: user/leader instruction → model/query → selected native tool → execution result → conversation/query continuation and next model decision; teammates also receive assigned tasks and return results/status to their leader. - Boundary reachability: src/entrypoints/cli.tsx initializes the shipped CLI; src/main.tsx and src/QueryEngine.ts bridge actual query results; src/tools/AgentTool/AgentTool.tsx invokes native src/tools/AgentTool/runAgent.ts, rather than merely naming an external model&#39;s independent tool orchestration. - Why this is / is not agent-owned: static files, locks, provider transports and a CLI argument parser would remain without the model but would not choose context-sensitive coding steps. The model controls operational actions; the human remains the request/approval owner. - Evidence: src/entrypoints/cli.tsx; src/main.tsx; src/query.ts; src/QueryEngine.ts; src/tools/AgentTool/AgentTool.tsx; src/tools/AgentTool/runAgent.ts. - Basis: structural + explicit. - Confidence: medium-high on source-level operating pathways. - Caveats: static source witnesses are not a benchmark or successful end-to-end execution trace of the large frozen bundle.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: reduce cross-S1 contention over the same outstanding team work, while respecting prerequisite dependencies and incompatible claims. - Disturbance / variety regulated: two operational teammates attempting to own the same work item, an agent simultaneously claiming overlapping obligations, or a successor task being picked before a blocking predecessor is complete. - Decisive decision or feedback right: atomic admission/rejection of a task claim relative to its owner, status, blockers and agent busy state; subsequent worker selection can attempt another eligible task. - Decision owner: first-party lock/claim protocol selects the conflict response deterministically; teammate/lead models select which task to attempt and can react to refusal, but there is insufficient evidence that an agent autonomously owns the S2-specific conflict regulation judgment. Thus constructor-level C rather than A. - Supporting / enforcement mechanisms: proper-lockfile, on-disk task state, dependency edges, owner/status markers, task watcher, background/in-process worker and mailbox notifications. - Closure path: two teammates examine shared work → per-list/per-task lock serializes claim → conflicting/blocked/busy claim rejected without duplicate owner, or valid claim recorded → watcher/runner receives result → worker proceeds only with admitted task or returns to next eligible-work check. - Distinct S1 units: at least two independently executing named team teammates with assigned operational work in the opted-in team mode. - Inter-S1 disturbance: simultaneous claims of the same task and dependency-order interference between their separate work units. - Attenuating coordination relation: exclusive task locks and atomic owner/dependency/busy checks prevent overlapping claims; dependency graph inhibits premature successor work. - Feedback into subsequent S1 behaviour: src/hooks/useTaskListWatcher.ts and src/utils/swarm/inProcessRunner.ts use claimTask success/failure to determine which task prompt is executed; src/tools/TaskListTool/TaskListTool.ts reports newly available/blocked tasks; failed submission releases a claim. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the claim operation explicitly recognizes competing owners and pending predecessor commitments and changes which S1 may act; the relation is not inferred solely from queue or message existence. - Boundary reachability: External users explicitly opt into a first-party team with ASTROCODEEXPERIMENTALAGENTTEAMS or --agent-teams; the supported team creation/AgentTool spawn path supplies actual teammates, and both useTaskListWatcher and inProcessRunner call the shipped claimTask before submitting work. The conflict check is a functional, not hypothetical, local distribution path. - Why this is / is not agent-owned: models decide their coding work, while fixed claim and lock code supplies collision-specific rejection. No independently evidenced agent right to revise this coordination protocol was established. - Evidence: src/utils/tasks.ts; src/hooks/useTaskListWatcher.ts; src/utils/swarm/inProcessRunner.ts; src/tools/TaskListTool/TaskListTool.ts; src/tools/TaskUpdateTool/TaskUpdateTool.ts; src/utils/agentSwarmsEnabled.ts. - Basis: structural. - Confidence: medium. - Caveats: restricted to the explicitly opted-in first-party team mode; manual TaskUpdate direct owner edits are not themselves guaranteed atomic claim operations.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: regulate the active team as a whole through owner/commitment allocation and responses to changing team status or blockers, not just assign one task for execution. - Disturbance / variety regulated: several active teammates with outstanding or blocked work, mismatched worker/tool capacity, idle workers, dependency bottlenecks and disputed responsibilities. - Decisive decision or feedback right: lead model chooses team composition and current work distribution, assigns/reassigns owners, adds dependencies, follows completion/blocked status, sends corrections to peers and authorizes shutdown/handoff of workers. - Decision owner: model-guided team-lead at the local team recursion. Static tools persist decisions but do not select which obligation/worker/priority should change. - Supporting / enforcement mechanisms: TeamCreate, TaskList, TaskUpdate, SendMessage, team roster, idle/status notifications and execution/worker lifecycle. - Whole-system current view: team roster, task list with ownership, status and blockedBy, team messages and idle/completion signals accessible to the lead rather than only a single worker&#39;s transcript. - Current-control decision scope: resource/worker assignment, reassignment, dependency constraints, requests for help, peer intervention and closing down the current team when work finishes. - Closure path: teammate result/blocked or idle signal → lead&#39;s shared current-team view and model judgment → owner/dependency/message/team roster update → next teammate claim/prompt/coding action reflects the lead&#39;s revised commitment. - Boundary reachability: In the explicitly enabled local first-party team mode TeamCreate registers the leader and shared task list, AgentTool starts named teammates, TeamCreate prompt and TaskList present the whole active obligations, and TaskUpdate/SendMessage return lead allocations and interventions to their teammates. These are not external hosted-controller rights. - Why this is / is not agent-owned: with the lead model removed the team file and tools can persist old assignments, but they do not autonomously select new priorities or settle which current work to reassign as the global situation changes. - Evidence: src/tools/TeamCreateTool/TeamCreateTool.ts; src/tools/TeamCreateTool/prompt.ts; src/tools/TaskListTool/TaskListTool.ts; src/tools/TaskUpdateTool/TaskUpdateTool.ts; src/tools/SendMessageTool/SendMessageTool.ts; src/tools/SendMessageTool/prompt.ts; src/utils/swarm/teamHelpers.ts; src/utils/agentSwarmsEnabled.ts. - Basis: structural + explicit. - Confidence: medium. - Caveats: positive only in first-party opted-in agent-team mode, not in the default single-coder mode. The lead&#39;s coordination authority is over current team obligations, not the user&#39;s organization or product ultimate policy.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S3* / direct audit: - State: ? - Function: possible separately instructed agent verification or artifact-review access, with unresolved frozen-distribution availability and consequential return path. - Disturbance / variety regulated: generated code or implementation reports could be incorrect, despite routine model narration and tests. - Decisive decision or feedback right: a separately running verifier would be able to investigate original claims from raw test/build/artifact evidence and return a challenging PASS/FAIL finding; the frozen code does not establish that this mode is operationally enabled for the public installation. - Decision owner: no confirmed accessible first-party S3 auditor at the declared third-party user boundary. A verification-role model is coded, but gated; the ordinary local /review prompt is executed through the same coder. - Supporting / enforcement mechanisms: src/tools/AgentTool/built-in/verificationAgent.ts supplies adversarial raw-command checking; src/tools/AgentTool/builtInAgents.ts requires feature(&#39;VERIFICATIONAGENT&#39;) and tenguhiveevidence (false default); src/constants/prompts.ts explicitly describes third-party default as off. src/tools/ReviewArtifactTool/ReviewArtifactTool.ts and src/tools/VerifyPlanExecutionTool/VerifyPlanExecutionTool.ts are throwing compatibility stubs. - Closure path: unresolved for supported public operation; if enabled, the built-in verifier&#39;s result would return to its parent and trigger rework/spot check. No supported, enabled source-backed end-to-end receipt was observed in the frozen installation. - Why this is / is not agent-owned: named adversarial verifier and local Git review instructions are promising but not sufficient to certify independently available complementary access and returned control at the assessed boundary. - Evidence: src/tools/AgentTool/built-in/verificationAgent.ts; src/tools/AgentTool/builtInAgents.ts; src/constants/prompts.ts; src/commands/review.ts; src/commands/review/ultrareviewEnabled.ts; src/commands/review/reviewRemote.ts; src/tools/ReviewArtifactTool/ReviewArtifactTool.ts; src/tools/VerifyPlanExecutionTool/VerifyPlanExecutionTool.ts. - Basis: explicit + unknown. - Confidence: medium on gated implementation, low on available whole-path audit. - Caveats: ? is a specific frozen code/feature availability gap, not a generic lack of independent reviewer. An external remotely billed ultrareview service is not borrowed as a first-party auditor. Positive audit needs a verified public build gate + independently sourced judgment + parent-control return.\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no evidenced first-party process creates externally prospective adaptation options and negotiates them back into present system capability at this recursion. - Disturbance / variety regulated: model choice, user task progress, external web results and external remote scheduling change operational input but do not constitute a future capability/adaptation conversation. - Decisive decision or feedback right: user/task models select current work; remote-agent scheduling is explicitly set up through user/hosted services rather than a first-party forward-looking strategy owner. - Decision owner: none established for S4 at the packaged local organization boundary. - Supporting / enforcement mechanisms: optional remote scheduling skill, web and model integrations, task planning and prompt memory. src/proactive/index.ts is a throwing compatibility stub. - Closure path: ordinary task information and human-configured triggers feed execution; no future external distinctions → adaptation option → current management/capability change cycle is evidenced. - Why this is / is not agent-owned: a roadmap, task plan, background agent, model fallback or remote scheduled job does not show an organization selecting adaptation based on prospective environment. - Evidence: src/skills/bundled/scheduleRemoteAgents.ts; src/proactive/index.ts; src/commands/ultraplan.tsx; src/commands/review.ts; src/tools/TaskCreateTool/TaskCreateTool.ts. - Basis: structural. - Confidence: medium within the inspected frozen public boundary. - Caveats: external organizational systems controlling remotely scheduled agents may have their own S4, but those owners are not inherited here.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no installed identity-level or ultimate-policy arbitration and binding returned governance loop was found. - Disturbance / variety regulated: local tool permission, plan approval, agent-team enablement and feature gating restrict operations but do not settle the identity/ethos of the assessed organization. - Decisive decision or feedback right: human user/operator chooses tasks, approves tools and enables modes; developers/feature service set static gates. These are not established ultimate-policy decisions on S3/S4 tensions. - Decision owner: no independently evidenced first-party S5 actor at this recursion. - Supporting / enforcement mechanisms: tool/agent permission schemas, team-tool gate, GrowthBook controls, project configuration and manual interventions. - Closure path: command or tool is accepted/denied inside a current task; there is no witnessed identity/policy issue → legitimate parent judgment → durable binding return affecting the organization&#39;s future conduct. - Why this is / is not agent-owned: human consent and compile/runtime access restrictions are not identity-governance, even where the model owns S1 coding and opt-in S3 current team control. - Evidence: src/utils/agentSwarmsEnabled.ts; src/services/policyLimits/index.ts; src/tools/AgentTool/AgentTool.tsx; src/tools/TeamCreateTool/TeamCreateTool.ts; src/tools/SendMessageTool/SendMessageTool.ts. - Basis: structural. - Confidence: medium-high for bounded negative. - Caveats: a broader team or company may make ultimate-policy choices external to this installation, not a first-party supported parent-governed mode.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/2cba0ce660eeed1dde178621a1932b92d1ce04e4/assessments/astro-code.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 2cba0ce660eeed1dde178621a1932b92d1ce04e4\">2cba0ce &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"2\" data-assessment-at=\"2026-10-23T01:29:49+03:00\"><th scope=\"row\"><a href=\"https://github.com/Gentleman-Programming/gentle-shell\" target=\"_blank\" rel=\"noopener\">gentle-shell</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>2</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-23\">2026-10-23</time></td><td class=\"review-ref\"><a href=\"https://github.com/Gentleman-Programming/gentle-shell/tree/407404372516ac0e27fc63e22ed08344f3f64c90\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 407404372516ac0e27fc63e22ed08344f3f64c90\">4074043 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: execute scoped coding and repository tasks, choosing inspection, edit, verification and subsequent repair actions based on results. - Disturbance / variety regulated: ambiguous change requests, unknown files, tool failures, failing tests, incomplete output and parent corrections. - Decisive decision or feedback right: supported Pi model tool loop and first-party focused worker definitions choose what to read/write/run and how to revise the next step. - Decision owner: parent or focused Pi worker model at the task level, subject to bounded edit and consent rules. - Supporting / enforcement mechanisms: stock Pi agent host, configured packaged worker definitions, pi --mode rpc execution, first-party task/receipt store and result return. - Closure path: user-scoped goal → model chooses tool/child actions → observes tool/check results → revises or returns evidence → parent accepts, redirects or reports partial work. - Boundary reachability: default installed gentle-pi extends Pi&#39;s supported native model loop and registers actually executable subagents; no evaluator-only or mocked agent is needed for the published execution route. - Why this is / is not agent-owned: the model&#39;s choice among investigation/edit/repair actions is discretionary; tool policy bounds effects but does not mechanically select code actions. - Evidence: packaged Pi extension, actual child process launcher, delegated writer contract. - Basis: first-party installable runtime and model-driven worker decision closure. - Confidence: high for structural action ownership, untested performance. - Caveats: Pi SDK and model provider are normal product dependencies; no live agent run was made in this review.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate concrete interference between independently running S1 agents in a shared clone/worktree, particularly duplicate concurrent privileged remediation. - Disturbance / variety regulated: a new remediation agent racing an existing queued or live remediation actor in the same worktree, and finite child process slots. - Decisive decision or feedback right: the runner rejects a conflicting same-worktree sdd-remediate launch and defers concurrent work to a bounded queue. The model parent can respond to the refusal, but no autonomous S2 conflict-arbitration judgment is established. - Decision owner: deterministic worktree-scoped admission rule and configured queue cap; parent model has a potential orchestration interface but the decisive collision check is fixed code. - Supporting / enforcement mechanisms: AgentRunner.run, task store, worktree-root validation, same-cwd remediation check, queue pump, per-child cancellation/status receipts. - Closure path: second S1 remediation launch asks for same worktree → first-party runner detects active conflicting remediation → rejects instead of starting → parent receives error and must preserve/cancel/wait for existing work → later launch may proceed once no actor holds that worktree lane. - Boundary reachability: native remediation launch flows through gentle-agents.ts and AgentRunner.run with the same-worktree collision guard, not just a protocol schema or maintainer test. - Why this is / is not agent-owned: prevention of inter-worker resource/correction collision is real, but fixed admission and limits rather than a situated agent decide the conflict; C is bounded to the existing S2 relation, not generic delegation. - Distinct S1 units: independent pi --mode rpc child remediation agents on separately queued requests; each would otherwise be empowered to edit/test within the same target worktree. - Inter-S1 disturbance: overlapping edits, correction/review artifacts and uncertain ownership when both remediation workers target the same repository state. - Attenuating coordination relation: one privileged remediation lane per worktree plus queue/resource admission; a second worker is refused until ownership is resolved. - Feedback into subsequent S1 behaviour: refused launch cannot start an interfering actor and returns a specific message to the parent; after cleanup the next child starts under the remaining scope. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: unlike task-list rendering, this check recognizes and blocks a specific clash in authority over shared worktree changes between separate workers. Other subagent status/ACK paths alone would not qualify. - Evidence: deduplicating admission guard, remediation scope authorization, subagent lifecycle. - Basis: shipped narrow cross-S1 interference attenuator without autonomous arbitration owner. - Confidence: moderate: clear conditional code path, limited to sdd-remediate requests and not all repository writers. - Caveats: maxconcurrency alone would only be generic resource limiting; the worktree-specific duplicate remediation refusal is the material positive witness. No conflict-free deployment was empirically tested.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A(P) - Function: hold current accountability over the bounded parent-session development campaign: select child responsibilities, inspect their progress, stop/redirect unfinished work and reconcile outcomes. - Disturbance / variety regulated: divergent child results, changed user scope, stalled worker, ambiguous verification, time/cost pressure and multiple current commitments. - Decisive decision or feedback right: model parent chooses when to delegate, who maps/writes/verifies and what to do with returned evidence. The attended human owner can separately inspect all child tasks of the session, stop an owned active child or steer new scope/next work. - Decision owner: model parent in standard agentic orchestration mode (A); interactive user as legitimate local workflow parent (P) through supported TUI/turn controls. - Supporting / enforcement mechanisms: delegated work-unit contracts, subagentrun/status/result/cancel/sendmessage, task widget/overlay, ownership checks, result events that initiate a parent turn. - Closure path: parent sees task plan and child status → selects/scopes writer, verifier or changed action → registered task executes or stops → child outcome/event returns to parent task context and updates current plan/delivery. - Boundary reachability: shipped assets/orchestrator-delegation.md injects parent-mode guidance and the installed gentle-agents.ts registers real actionable tools; TUI shows active same-session tasks and provides stop/scope navigation to the human. - Why this is / is not agent-owned: the parent model judges which work to hand off or repair in relation to other commitments, not only mechanically queues known inputs; human task intervention is a separate explicitly supported mode. - Whole-system current view: for the chosen recursion, subagentlisttasks, status, result and the task overlay cover current own-session workers, queued/running state and retained outcomes; cross-session peers are presence-only and not claimed as a whole distributed enterprise view. - Current-control decision scope: delegation topology, worker/verification assignment, stop, continue and reconciled delivery for the current session&#39;s campaign, as opposed to generic concurrency/timeouts. - Evidence: parent orchestration contract, runtime tools, parent task control and UI. - Basis: scoped current-portfolio agentic control and distinct attended human intervention, not broad cross-repository strategic planning. - Confidence: moderate because the model is prompted to own reconciliation but live compliance is not evaluated. - Caveats: the local-session view excludes other process&#39;s action authority; an ACK from a separate session is not completion or control.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: separately audit S3&#39;s live parent orchestration/portfolio-management assertions and return management correction through an independent evidence channel. - Disturbance / variety regulated: errors in allocation, supervising, prioritizing or reconciling the parent-managed set; no S3-audit closure established. - Decisive decision or feedback right: native review lenses, refuter and verification concern the exact code-change candidate, not independent judgments about the parent session&#39;s management choices; their lifecycle and risk classification additionally belong to the separate Go provider. - Decision owner: no independent S3-audit decision owner in the assessed Pi-extension local-recursion mode. - Supporting / enforcement mechanisms: optional candidate-frozen reviewer completions, delegated verifier and immutable review status/receipts from external provider. - Closure path: not applicable as S3; artifact findings return to delivery/repair, not a separate evaluation of S3&#39;s allocation or intervention claims. - Why this is / is not agent-owned: genuinely separate review of a code diff is important S1 acceptance evidence, but neither its claim nor independent access is directed at the S3 owner&#39;s management reality. - Evidence: provider review ownership, delegated verification boundary, native authority map. - Basis: bounded negative at local parent-session portfolio recursion. - Confidence: high for inspected reviews, moderate for other unenumerated external companion integrations. - Caveats: excludes external Go provider as an independent organizational function; even including its ordinary diff audit would not by itself constitute S3-management audit.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S4 / adaptation: - State: C(P) - Function: assess skill deficiencies seen during work and prepare improvements to reusable future worker capability; in an explicit parent mode accept and write improvements for later projects/tasks. - Disturbance / variety regulated: drifting task methodologies, outdated or conflicting skill activation instructions, cumbersome skill bodies and recurring retrieval/usage mistakes. - Decisive decision or feedback right: model-led shipped skill-improver generates bounded audit findings/proposed rewrites (C), but it defaults to audit-only. A human asking to apply changes authorizes actual writing of improved SKILL.md, which the registry reindexes for later use (P). No automatic autonomous future-capability adoption or self-selected learning cadence was established. - Decision owner: assistant model for candidate skill auditing; local human owns the distinct affirmative future-capability application decision. - Supporting / enforcement mechanisms: packaged skills/skill-improver/SKILL.md, style gate, allowlisted edits, skill registry scanner/watch and project-vs-global precedence. - Closure path: evidence from existing skill usage/audit → model identifies a reusable skill problem and a revised form → person explicitly requests apply → persisted SKILL.md changes → skill-registry notices/scans revision → later task loads matching updated instruction. - Boundary reachability: the improver and registry are both shipped first-party skills/extensions; no Engram installation is required for filesystem skill reuse. The human apply mode is not the default; no autonomous S4 owner is implied. - Why this is / is not agent-owned: the proposed content is model-authored but selecting whether durable methodology changes govern future tasks is a human decision, so the positive base is only constructor C, with closed explicit parent mode P. - External distinction: observed deficiencies in actual on-disk skill instructions, task audit outcomes and user-supplied correction requirements—not the current worker merely retrying its patch. - Future / prospective distinction: changing skill activation/format affects later independent tasks by changing their available procedure, not just resolving the current deliverable. - Adaptation option generated: recommended corrections to skill metadata, trigger, structure, rules and decision table; safe apply may rewrite the skill and refresh the index. - Path back into current capability / S3: updated skill file becomes the new source of truth, indexed at .atl/skill-registry.md and routed into subsequent delegated work. - Evidence: first-party skill improver, registry operational skill, actual file-scanning registry extension, companion-memory boundary. - Basis: narrow first-party agent-proposal plus user-approved prospective procedural adaptation; no claim of autonomous ongoing learning. - Confidence: moderate; a supported apply protocol and future registry ingestion, not observed actual post-edit gain. - Caveats: skill-improver is invoked for requested skill improvement, not passively after every run; Engram and external adaptive memory products are excluded. This does not establish unsupervised S4=A.\">C(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S5 / identity: - State: P - Function: set persistent permitted scope for the local coding workflow and ultimate authority over consequential operations and how future subagents may operate. - Disturbance / variety regulated: conflicts between repository/user restrictions and tool-generated actions, new sensitivity to destructive commands, background autonomy and attempted widening of approval scope. - Decisive decision or feedback right: local human owns project/global durable runtime-guardrails.json allow/confirm/block settings and background-subagents.json; per-session review/remediation authorizations and ordinary delivery remain subject to a human-controlled repository policy. - Decision owner: legitimate self-hosted project owner (P), not the code reviewer, delegated worker or remote OSS maintainer. - Supporting / enforcement mechanisms: first-party runtime config decoder, project-over-global precedence, guarded tool intercepts and interactive consent, session/repository-bound approval identity and fail-closed refusals. - Closure path: human establishes project/global normative guardrails and delegation mode → persisted config is read into the installed session → sensitive commands are allowed/confirmed/blocked accordingly → workers act only under the resulting policy; new consequential authority is escalated for approval. - Boundary reachability: extensions/gentle-ai.ts loads project/global guardrail policy on the production Pi path, and lib/background-subagents-policy.ts is called by gentle-agents.ts to choose child scheduling mode. This is durable local normative control, not individual PR acceptance alone. - Why this is / is not agent-owned: the enduring rule contents and ultimate delivery/authorization identity are supplied by the user; the model acts within—not as the author of—those constraints. - Evidence: guardrail policy resolution, background delegation policy, session standing review permission, delivery separation. - Identity / ultimate-policy issue: whose standing development and safety boundaries determine what the installed local coding assistant is allowed to do across later tasks. - Ultimate authority in each claimed mode: human owner (P); neither the native reviewer nor child tool has authority to rewrite user-confirmed global/project policy. - Return-to-operation path: project/global files set behavior for subsequent tool interception and background delegation; the session/review consent gate halts unauthorized actions. - Basis: durable local operator-owned policy loop with runtime enforcement. - Confidence: moderate-high for scoped standing safety/workflow policy, not external maintainer governance. - Caveats: GENTLEPIAUTONOMOUSMODE=1 is an explicit operator-selected override; this is still parent-granted, not agent-owned ultimate policy. Some actual safe handling depends on the underlying Pi host and external review provider.\">P</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/99795066d57e02db7386e2b0dc2420ec91668165/assessments/ge/gentle-shell.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 99795066d57e02db7386e2b0dc2420ec91668165\">9979506 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"2\" data-assessment-at=\"2026-10-11T23:24:50+03:00\"><th scope=\"row\"><a href=\"https://github.com/AlysisAi/alysis-code\" target=\"_blank\" rel=\"noopener\">Alysis Code</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>2</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-11\">2026-10-11</time></td><td class=\"review-ref\"><a href=\"https://github.com/AlysisAi/alysis-code/tree/ff6682acb4a339dbbf9ce687c46374ce536ad641\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision ff6682acb4a339dbbf9ce687c46374ce536ad641\">ff6682a &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Autonomous local coding session accepts user task, calls model and host-approved file/shell/verification tools and iterates on returned observations; model-driven focused child sessions can execute scoped coding tasks. - Disturbance / variety regulated: User requirements, evolving code and tests, tool errors, sandbox conditions, provider responses. - Decisive decision or feedback right: Choose task-specific source edits, inspections and verification work after reading direct tool feedback. - Decision owner: First-party provider-driven Alysis Code agent model and separately model-driven bounded child Session where explicitly delegated. - Supporting / enforcement mechanisms: CLI alysis chat/alysis run, turn.core controller, first-party tool assembly, permission/sandbox enforcement, model turn history. - Closure path: Request → model/tool choice → allowed action → observations and completion/repair evidence → next model step/final. - Boundary reachability: Official alysis-code package CLI binds workspace and creates first-party runtime; code paths and documentation agree. - Why this is / is not agent-owned: Coding choices are genuinely model-selected; deterministic sandbox and completion constraints do not replace these decisions. - Evidence: docs/architecture.md; src/alysiscode/main.py; src/alysiscode/agent/turn/core.py; src/alysiscode/agent/verification.py - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: Prevent simultaneous independently executing child coding sessions from corrupting a shared worktree or merging incompatible work. - Distinct S1 units: subagentrun/subagentspawn create first-party nested sessions with model instructions and their own tools; Forge swarm workers also work in isolated tasks. - Inter-S1 disturbance: Two write-capable children working in the same parent repository can race on the same files or overwrite the other&#39;s candidate; read-only helpers may inadvertently mutate the shared root. - Attenuating coordination relation: Shared write-capable child runs are serialized; parallel writers use separate detached worktrees, guarded conflict-aware subagentapply, and dependency/release pinning. Swarm batch scheduler requires disjoint precise claimed path scopes; overlap forces a separate batch. - Feedback into subsequent S1 behaviour: A conflicting task is deferred/serialized, and candidate apply returns fail-closed conflict or a successfully integrated patch; parent receives bounded child outcomes before choosing further work. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: The system regulates concrete interference among concurrently acting child S1s through worktree isolation and overlap-based batch admission, not just assigning tasks or passing messages. - Disturbance / variety regulated: Concurrent child edits, overlapping file claims, source-worktree release before checker completion. - Decisive decision or feedback right: Select safe concurrent subset, delay incompatible child writes, enforce isolated candidate release/apply. - Decision owner: Deterministic host SubagentWorkspaceProvider, batch scheduler and host admission constructor rather than an independent coordinating model. - Supporting / enforcement mechanisms: Detached Git worktrees, overlap checker, release-pin lock, patch conflict detection, staged task dependencies and child registry. - Closure path: Competing child requests → runtime scope/worktree admission → safe execution or deferral → conflict-aware integration → returned parent result. - Boundary reachability: Documented CLI child modes and Forge swarm are implemented in first-party packages; positive claim bounded to concurrent child/isolation modes. - Why this is / is not agent-owned: Agent may choose delegation, but inter-child safety policy is enforced by the runtime. - Evidence: docs/subagents.md; src/alysiscode/agent/subagentworkspace.py; src/alysiscode/swarmscheduler.py; src/alysiscode/swarmorchestrator.py - Basis: structural / explicit -\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3 / regulation: - State: C - Function: Maintain a whole-current Forge run&#39;s task states, dependencies, acceptance, integration health and continuation under a first-party plan/control cycle. - Whole-system current view: Forge canonical plan and task-status ledger cover all current tasks (runnable, blocked, executing, failed, and awaiting integration), explicit dependencies and changed-path/write scope, plus batch integration evidence. The swarm orchestrator assembles this whole-current picture before admitting subsequent units. - Current-control decision scope: Host Forge/Swarm controller authoritatively chooses which child tasks are runnable together, blocks dependencies or overlapping write scopes, accepts/rejects integration verified batches, updates canonical task states, and optionally recomputes the schedule after validated current-run replanning. This authority crosses multiple S1 task workers rather than operating within one producer&#39;s tool turn. - Disturbance / variety regulated: Individual child failure, unmet prerequisites, incompatible candidate branches, integration verification failures, scope drift and blocked tasks. - Decisive decision or feedback right: Determine runnable task batches, disallow blocked/dependency-unsatisfied work, reject failed integration, record authoritative task state, and recompute tasks/plan when admissible replanning changes it. - Decision owner: Deterministic Forge/Swarm orchestrator control constructor with optional model replanning constrained by validation and run mode; not an independently chartered model S3 manager. - Supporting / enforcement mechanisms: Canonical plan/run ledger, TaskCandidate/Schedule, explicit task statuses and dependencies, integration-gate verification, replan bookkeeping and merge guards. - Closure path: Whole-run task-status/dependency view → select runnable work → execute children → inspect integration results → approve/reject merge and update task/run states → recalculate plan/schedule for subsequent work. - Boundary reachability: Shipped alysis forge run, forge exec, forge swarm bind this control plane to plan-driven user tasks; ordinary single chat need not run Forge. - Why this is / is not agent-owned: Current plan-level authority is host-owned; it makes binding decisions across multiple child tasks and is therefore C rather than A. One-shot completion gate alone would not warrant organization-level S3. - Evidence: docs/forge.md; src/alysiscode/swarmscheduler.py; src/alysiscode/swarmorchestrator.py; src/alysiscode/forge.py - Basis: structural -\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: Independently inspect a produced coding candidate via separate first-party verifier/code-reviewer model session, with direct access to the frozen candidate worktree and consequential feedback for parent admission. - Claim being audited: A completed write-capable child reports a valid modification satisfying the parent&#39;s task and required verification. - Ordinary reporting path: Producing child returns its own bounded summary/tool events; parent could otherwise trust the child-provided report. - Complementary access path: A separate read-only verifier or code-reviewer subagent is launched with workspacefromrun=&lt;writerrunid&gt;, pointing to the completed unreleased Git worktree itself, rather than solely the writer&#39;s claim. Deterministic independent host acceptance/execution evidence is also collected by the completion certificate. - Independence boundary: Separate subagent model invocation and direct candidate-source view provide a first-party complementary route, not independent OpenSiro external reviewer or verified cross-provider separation. - Who acts on findings: Verifying child returns bounded outcome; parent can resume worker for correction or discard, and calls subagentapply only after accepting the verifier result. Host worktree release locks prevent apply/discard while the reading verifier is running. - Disturbance / variety regulated: Hallucinated completion, wrong patch semantics, scope violations, failing verification of produced candidate. - Decisive decision or feedback right: Read the candidate in a separately bounded model session and make a task-specific verifier judgment; parent uses findings to withhold admission and request repair. - Decision owner: Configured separate verifier/code-reviewer model session (A), assisted by deterministic host evidence gate (C); no automatic universal audit guarantee. - Supporting / enforcement mechanisms: Pinned source-worktree reader, wait/join and dependency chain, read-only roles, candidate release lock, acceptance certificate, verification evidence. - Closure path: Write child finishes → separate verifier reads exact candidate → model verdict returned to parent → parent applies only if accepted or routes back via subagentresume → candidate admitted/discarded. - Boundary reachability: Documented first-party subagentspawn, subagentwait, workspacefromrun, subagentapply are available in supported top-level chat/one-shot modes; this mode must be specifically requested or chosen by the parent and is not Forge default. - Why this is / is not agent-owned: The verifier, unlike the deterministic completion gate or same-model adversarial nudge, is a distinct model actor with raw-source access and own evidence-directed judgment. - Evidence: docs/subagents.md; src/alysiscode/agent/subagentexecution.py; src/alysiscode/agent/subagentworkspace.py; src/alysiscode/agent/verification.py; src/alysiscode/agent/turn/core.py - Basis: structural / explicitly documented - Confidence: medium-high for audit opportunity, medium for realized efficacy - Caveats: Verifier call is optional, user/parent-led and can report incomplete or fail; independent model execution does not imply independent outside organization. An adversarialfinalize self-model nudge alone would only be a weaker constructor.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No sufficiently evidenced prospective external environment intelligence that produces and deploys organization-wide future strategic capability changes at this recursion. - Disturbance / variety regulated: Provider/model changes, future task needs and learned recurring issues are possible external signals but not shown as an owned prospective intelligence cycle. - Decisive decision or feedback right: Current Forge replanner can amend immediate plan on integration failure, not conduct future environment sensing with capability options. - Decision owner: User/operator policy and current task model/plan repair; no independent S4 owner. - Supporting / enforcement mechanisms: Replanning, memory, plugins, skill loading, extension docs and historical feedback bundles. - Closure path: Immediate failure → revised current task schedule, not outside-and-then option → accepted future capability change. - Why this is / is not agent-owned: Current-run replanning is S3; memory and optional extensibility are supporting surfaces rather than prospective strategic intelligence. - Evidence: src/alysiscode/swarmorchestrator.py; src/alysiscode/replanning.py; docs/architecture.md - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No distinct agent-owned or organization-legitimate ultimate policy and identity deliberation loop with binding returned changes. - Disturbance / variety regulated: Approval, sandbox escapes, tool scopes and user trust preferences. - Decisive decision or feedback right: Human/operator sets security policy, execution mode and approvals; host enforces them. - Decision owner: Operator and host policy machinery, not an S5 authority that deliberates organizational identity. - Supporting / enforcement mechanisms: Sandbox permission modes, trusted configuration restrictions, approval scopes and execution hooks. - Closure path: Tool action → deterministic allow/deny or human approval; no ultimate-policy/identity issue → legitimate deciding organ → binding policy feedback. - Why this is / is not agent-owned: Host-owned safety rails and reviewer veto do not create a sovereign identity/policy organ. - Evidence: docs/architecture.md; docs/securitymodel.md; src/alysiscode/approvalscope.py - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/3eda0f415511089d2312c1c3838878f4cccdbf79/assessments/alysis-code.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 3eda0f415511089d2312c1c3838878f4cccdbf79\">3eda0f4 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-18T00:51:56+03:00\"><th scope=\"row\"><a href=\"https://github.com/PrimeIntellect-ai/prime-agent\" target=\"_blank\" rel=\"noopener\">Prime Agent</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-17\">2026-09-17</time></td><td class=\"review-ref\"><a href=\"https://github.com/PrimeIntellect-ai/prime-agent/tree/66abc2a604fc42a220292a1ca4cf33ee60cb5733\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 66abc2a604fc42a220292a1ca4cf33ee60cb5733\">66abc2a &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: A. First-party model-driven agents autonomously execute coding/research work through tools and the persistent control environment.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: —. Recursive spawning, direct messaging and parent/child communication establish delegation and communication, but the reviewed evidence does not identify a specific peer-S1 interference/conflict/oscillation together with an S2-specific attenuation and feedback loop. The earlier proposal&#39;s C treated generic composability as coordination evidence.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: A. The parent agent can inspect the current child registry/status and make discretionary whole-subtree intervention decisions such as spawning additional work, issuing follow-ups and terminating/deleting child work. Those decisions change subsequent current operation; host budgets/lifecycle controls are supporting enforcement.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: —. Quality gates and refinement evidence are normal validation/optimization mechanisms. No sufficiently independent first-party audit actor with complementary access and a distinct audit judgment feeding corrective current control was established at the pin.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: —. Continual Harness performs real durable refinement from operational trajectories, but learning/self-improvement alone is not S4. The reviewed path does not establish an outside-and-then environmental intelligence distinction that generates prospective adaptation options and returns them into present capability.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: —. Base goals, task objectives and parent-supplied configuration constrain the agent but do not form an operationally closed identity/ultimate-policy loop. Parent ownership of a goal by itself is not P.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/f17df7784f951d191718bb7504b7770132a18a8a/assessments/prime-agent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit f17df7784f951d191718bb7504b7770132a18a8a\">f17df77 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-10-15T00:11:55+03:00\"><th scope=\"row\"><a href=\"https://github.com/pentoshi007/clai\" target=\"_blank\" rel=\"noopener\">clai</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-15\">2026-10-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/pentoshi007/clai/tree/630d85f9eb7c2b5b3e499c503abf5834610c6939\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 630d85f9eb7c2b5b3e499c503abf5834610c6939\">630d85f &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: perform open-ended user-directed coding/security-investigation tasks by selecting and iterating real actions on source and observed evidence. - Disturbance / variety regulated: unknown code structure, failing commands/tests, changing files, HTTP/terminal output, incomplete task facts and model errors/limits. - Decisive decision or feedback right: the model chooses relevant operations/tool arguments, reacts to actual tool results, can continue or stop, and can request bounded independent investigation in orchestration mode. - Decision owner: first-party model-directed main clai agent; separately instantiated read-only child model loops own their own bounded investigations while provider inference is external. - Supporting / enforcement mechanisms: tool schema/routing, permission/scope gates, terminal and FS tools, context recovery, durable task plan, result capture and provider key retry. - Closure path: user objective and current workspace evidence → model selects tool → first-party execution and guard → output/denial/error returned to model → next action, delegation, or final answer. - Boundary reachability: shipped CLI initializes the first-party runner and dispatches model tool calls, while the optional shipped SubagentManager connects first-party model-backed investigator workers; neither depends on a separate external agent binary. - Why this is / is not agent-owned: removing model-directed tool/next-action choices leaves deterministic execution and policy checks, not a task-sensitive coding actor. - Evidence: src/agent/runner.ts; src/agent/turn/loop/run-rounds.ts; src/agent/turn/tool-execution/single-tool.ts; src/agent/subagents/worker.ts; README.md. - Basis: explicit + structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no materially closed shipped coordination of a specific interacting-S1 interference despite parallel context-gathering child loops. - Disturbance / variety regulated: potential duplicate evidence gathering, resource consumption, conflicting conclusions and overlapping investigative effort among children. - Decisive decision or feedback right: SubagentManager.assertUnique blocks an exact repeated assignment before it launches; assertCapacity limits concurrent instances, while prompt guidance asks for unrelated scopes. No worker-to-worker discrepancy/oscillation detection and corrective inter-S1 feedback right is established. - Decision owner: fixed admission guards and task-allocation instructions, not an autonomous S2 conflict owner. - Supporting / enforcement mechanisms: SHA-256 assignment fingerprint, three-slot hard cap, read-only tool restrictions, event/report transport and parent tool selection. - Closure path: rejected duplicate submission returns an error to the parent before a second child exists; individual child reports return to the parent for task use. No observed or structurally wired conflict between existing S1s is tracked/attenuated with a subsequent worker-response loop. - Why this is / is not agent-owned: preventing a duplicate request at the tool interface and serializing receipt of results do not demonstrate regulation of interactions among already operative S1 cells. - Evidence: src/agent/subagents/manager.ts; src/agent/subagents/tools.ts; src/agent/subagents/worker.ts; src/tools/definitions/subagents.ts. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: manage current, parallel operational investigation commitments and capacity under one active coding session. - Disturbance / variety regulated: competing child research assignments, unfinished or irrelevant investigations, cancellation/reprioritization needs, saturation of the three-worker capacity and partial/incomplete reports. - Decisive decision or feedback right: main model views active child roster/status/results, chooses distinct assignments to start, may stop/correct/restart tasks, await any completed child, and integrates verified findings into subsequent main work. - Decision owner: first-party model-directed main agent as current controller over several distinct read-only operational S1 cells; SubagentManager enforces commands and capacity. - Supporting / enforcement mechanisms: session-scoped child map, list/read/wait/stop/restart tool API, abort controllers, per-child event/report state, shared model system guidance and maximum-concurrency guard. - Closure path: whole-session current child states and pending research needs → parent model start/stop/restart/dependency decision → SubagentManager action on target child → updated status/return report → parent model subsequent assignment/implementation choices. - Boundary reachability: src/agent/runner.ts includes orchestration guidance in first-party agent context, src/agent/turn/tool-execution/single-tool.ts dispatches runSubagentTool, and manager.ts supplies live child control; enabled orchestration mode is a shipped operator-supported mode rather than an unconnected API. - Why this is / is not agent-owned: holding the manager&#39;s maps and hard cap fixed without parent model decisions would not select appropriate parallel research scopes, react to different child results, or redirect current effort with task discretion. - Whole-system current view: active session&#39;s primary task and each running, stopping or completed child investigation, identified assignments, last events/results and available capacity; not global company or other users&#39; sessions. - Current-control decision scope: assign independent evidence tasks, allocate up to three child work cells, stop obsolete work, restart with revised instructions, await and use outcomes to reprioritize current coding investigation. - Evidence: src/agent/subagents/manager.ts; src/agent/subagents/tools.ts; src/tools/definitions/subagents.ts; src/agent/runner.ts; src/agent/turn/tool-execution/single-tool.ts. - Basis: explicit + structural - Confidence: medium-high - Caveats: credited only in enabled multi-investigation mode, not every default single-task execution. No free-standing automated watchdog, multiwriter fleet or parent-governed (P) mode asserted.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no distinct built-in independent audit of execution outcomes with authoritative corrective return. - Disturbance / variety regulated: wrong code, unjustified success claims, missed tests and inaccurate tool/evidence reports. - Decisive decision or feedback right: the main task agent runs tools, interprets test results and verifies claims; optionally delegated read-only workers deliver research reports whose instructions explicitly say the parent verifies them, rather than an independent auditor passing judgment over an operational claim. - Decision owner: primary agent for normal self-checking and report use; no materially distinct S3 owner established. - Supporting / enforcement mechanisms: evidence governor, progress confirmation, terminal/test outputs, read-only context gatherers, post-task plan status and human scope approvals. - Closure path: the original S1 interprets evidence and may continue; no separate reviewer opinion about completed S1 output is wired to corrective control independently of the originating task actor. - Why this is / is not agent-owned: model-backed investigator children are real, but they are general delegated research operations; they do not automatically constitute the complementary audit function merely by reading files. - Evidence: src/agent/subagents/worker.ts; src/agent/subagents/tools.ts; src/agent/evidence-governor.ts; src/agent/task-evidence.ts; src/agent/runner.ts. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no closed organization-level outside/future intelligence/option-development path beyond current task investigation and provider resilience. - Disturbance / variety regulated: future environmental/tool changes or project direction might require capability adaptation, but the supported agent loop is goal/current-task oriented. - Decisive decision or feedback right: agent can investigate present questions, user may switch providers/skills, system rotates keys when failing, and task history persists; none is a demonstrated future capability adoption decision. - Decision owner: task-level model for tactical research, deterministic fallback for current provider failure, operator for tools/skills settings; no distinct S4 owner. - Supporting / enforcement mechanisms: provider fallback/rotation, memory/compaction, workspace-context summaries, read-only investigations, skill discovery and existing-session continuation. - Closure path: present facts or fallback errors change next task action/model selection, not a future/environmental adaptation option selected and returned to durable system capability or whole-current S3. - Why this is / is not agent-owned: tactical research and resource recovery serve active S1 rather than shifting the organization&#39;s future strategy/capability. - Evidence: src/agent/runner.ts; src/agent/subagents/worker.ts; src/agent/context-manager.ts; src/agent/task-analyzer.ts; README.md. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no legitimate decision/return channel for constitutional project identity, purpose or ultimate policy of the installed agent organization. - Disturbance / variety regulated: unsafe shell actions, out-of-scope pentest targets, provider/payment preferences and consent to destructive tools are real operational constraints. - Decisive decision or feedback right: operator specifies engagement scope and risk/approval limits; first-party controls enforce those limits on tool invocations rather than resolving organization-identity disputes. - Decision owner: human user/config for scope/consent and deterministic runtime guards for validation; no first-party ultimate-policy S5 decision owner. - Supporting / enforcement mechanisms: scope-based target allowlists/denylists, rate/concurrency caps, DNS/redirect checking, safe/confirm/block rules, cost/free-only configuration and user confirmation prompts. - Closure path: tool action allowed/denied/confirmed changes its execution; no identity/policy issue escalates to a legitimate parent who settles purpose and returns an organization-wide governing decision. - Why this is / is not agent-owned: the model may propose a task outside allowed scope, but cannot legitimately redefine the operator&#39;s ultimate constitutional rules through approval/tool output. - Evidence: README.md; src/agent/session-policy.ts; src/agent/turn/tool-execution/authorization.ts; src/agent/turn/tool-execution/gates.ts; src/agent/scope-context.ts. - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/6fc704c99e84a88d45b66dad0cc208f97cb53933/assessments/clai.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 6fc704c99e84a88d45b66dad0cc208f97cb53933\">6fc704c &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"3\" data-assessment-at=\"2026-09-29T12:57:56Z\"><th scope=\"row\"><a href=\"https://github.com/tangle-network/agent-runtime\" target=\"_blank\" rel=\"noopener\">Tangle Agent Runtime</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>3</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-29\">2026-09-29</time></td><td class=\"review-ref\"><a href=\"https://github.com/tangle-network/agent-runtime/tree/ed008c7623362720c47b1e628dbc19073e196b91\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision ed008c7623362720c47b1e628dbc19073e196b91\">ed008c7 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: perform delegated task work through agentic worker loops. - Disturbance / variety regulated: changing task state, tool/environment results, failures, missing information, and backend/provider responses. - Decisive decision or feedback right: choose substantive next actions from current task observations. - Decision owner: executing model-driven worker agent. - Supporting / enforcement mechanisms: worker executors/backends, Agent.act, tool/harness integration, scope lifecycle, retries, accounting, and settlement. - Closure path: assigned task → worker inference/action → environment/tool result → later worker decision → operational output. - Boundary reachability: workers are the normal execution units of shipped supervise/Supervisor paths. - Why this is / is not agent-owned: host code constrains and executes actions, while model cognition owns substantive next-action choice. - Evidence: docs/architecture.md; src/runtime/supervise/types.ts. - Basis: explicit + structural. - Confidence: high. - Caveats: provider-side cognition remains external; credit is for the first-party execution loop around it.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate resource contention among concurrently active child S1 units sharing finite execution capacity. - Disturbance / variety regulated: concurrent children can jointly request more tokens, USD, iterations, named resources, or live-worker slots than the parent can commit safely. - Distinct S1 units: concurrently executing child agents in one recursive supervisor tree. - Inter-S1 disturbance: simultaneous child reservations contend for one finite parent-owned resource pool; uncontrolled admission could overcommit capacity. - Attenuating coordination relation: first-party BudgetPool reserves enforced channels atomically, rejects insufficient admission, reconciles actual spend, refunds known unused capacity, and restores reservations conservatively after recovery. - Feedback into subsequent S1 behaviour: typed spawn rejection/shortfall and changed free capacity return into the live manager path and affect later spawn/work choices. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the witness is a concrete cross-worker finite-resource interference plus an atomic attenuation mechanism, not messaging or delegation alone. - Decisive decision or feedback right: runtime deterministically decides whether a requested reservation fits; a composed manager chooses what to do after refusal or changed capacity. - Decision owner: no autonomous S2 owner is established by the deterministic reservation mechanism itself. - Supporting / enforcement mechanisms: conserved budget pool, atomic reservation/reconciliation, root-wide worker cap, fail-closed unknown measurements, typed spawn rejections/shortfalls. - Closure path: competing child commitments → reserve/reject atomically → capacity/refusal visible to manager → subsequent work choices operate under reconciled capacity. - Boundary reachability: budget admission is part of shipped recursive Scope/supervise execution across nested children. - Why this is / is not agent-owned: the S2-specific mechanism is first-party, but its collision arbitration is deterministic rather than autonomous, so constructor credit is used. - Evidence: src/runtime/supervise/budget.ts; src/runtime/supervise/scope.ts. - Basis: explicit + structural. - Confidence: medium-high. - Caveats: generic shared budgets are not credited by themselves; credit rests on finite cross-child contention and fail-closed admission/reconciliation.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: maintain a current view of the supervised tree and exercise present-tense authority over commitments, steering, cancellation, and further allocation. - Disturbance / variety regulated: active workers can stall, fail, drift, need redirection, finish asynchronously, or leave the parent objective incomplete while capacity changes. - Whole-system current view: one authoritative Scope exposes the live child set, progress/events, settlements, spend/reservations, and recursively nested execution state to the manager path. - Current-control decision scope: spawn, await/observe, steer, stop/cancel, react to completion checks, and choose the next move under current resource/depth/concurrency limits. - Decisive decision or feedback right: decide which worker commitments to create, continue, redirect, or terminate and when the objective is complete enough to stop. - Decision owner: model-driven supervisor/driver agent in the shipped supervise/coordination path. - Supporting / enforcement mechanisms: Scope, Supervisor, coordination tools, journals/recovery, progress/trace access, budgets, worker caps, cancellation, and completion gating. - Closure path: live worker/resource state → supervisor model decision → runtime applies spawn/steer/stop/etc. → changed tree state returns through the same scope. - Boundary reachability: public supervise(profile, task, opts) is explicitly a manager agent driving workers under one budget. - Why this is / is not agent-owned: deterministic machinery enforces constraints, while the supervisor model chooses dynamic topology/intervention at runtime. - Evidence: README.md; docs/canonical-api.md; src/runtime/supervise/scope.ts. - Basis: explicit + structural. - Confidence: high. - Caveats: this positive state is specific to the supported model-driven supervisor mode, not every fixed topology/combinator.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: check operational claims/results through evidence paths that do not rely on the producing worker&#39;s own success assertion and return findings into control. - Disturbance / variety regulated: a worker can claim completion despite a wrong result, or ordinary worker reporting can omit failures visible in direct output/trace evidence. - Claim being audited: whether worker output satisfies the parent deliverable and, for analyst routes, what failures/patterns appear in worker tool-trace evidence. - Ordinary reporting path: worker settlement/final output and normal progress/results returned to the parent. - Complementary access path: parent completion checks execute against actual worker output; trace analysts can read structured worker trace evidence and publish findings separately from worker prose. - Independence boundary: check/analyst execution is outside the producing worker self-report path; the external final judge stays write-only/outside steering and is not borrowed as an internal owner. - Who acts on findings: supervisor/driver consumes failed completion or routed analyst findings and can revise acceptance/continuation/steering. - Decisive decision or feedback right: runtime supplies independent evidence/check/finding-return structure; deployment supplies substantive check/analyst semantics in the general case. - Decision owner: no guaranteed autonomous first-party auditor exists in every base deployment; a composed verifier/analyst can own the judgment. - Supporting / enforcement mechanisms: completion gate, verifier/check APIs, trace evidence, analyst routes, finding events, and judge-to-steering firewall. - Closure path: worker output/trace → independent check/analyst path → pass/fail/finding → supervisor changes acceptance/continuation/control. - Boundary reachability: completion-gated delivery and analyst coordination mechanisms are shipped runtime surfaces, while substantive audit configuration remains composition-dependent. - Why this is / is not agent-owned: the first-party constructor closes evidence and feedback paths but not a mandatory autonomous auditor, so constructor credit is used. - Evidence: docs/architecture.md; src/mcp/tools/coordination.ts. - Basis: explicit + structural. - Confidence: medium-high. - Caveats: the external benchmark judge is intentionally excluded from the execution-control tree and is not used to inflate this state.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S4 / adaptation: - State: C - Function: construct and independently measure candidate changes to agent/profile/code surfaces for later operation while separating search from final assessment and activation. - Disturbance / variety regulated: current configuration may underperform on fresh/future work; search may overfit or mutate live state before independent validation. - External distinction: improvement consumes caller-supplied scenarios/objectives and can use production/search findings about environment/domain performance outside the current execution tree. - Future / prospective distinction: train/selection/final-test separation asks whether a changed surface should improve subsequent runs rather than merely finish the current action. - Adaptation option generated: optimization methods/candidate generators produce changed profile/code/tool/MCP/memory surfaces with exact candidate identity/diffs. - Path back into current capability / S3: selected candidates are independently final-tested, bound into review/activation records, and can become later runtime state after an authorized application-owned atomic write. - Decisive decision or feedback right: runtime owns candidate identity, measurement binding, final-test isolation, review/activation records, and result validation; caller/application owns domain objective/execution and final adoption write. - Decision owner: no autonomous first-party S4 actor closes the complete domain sensing→adaptation→adoption loop alone. - Supporting / enforcement mechanisms: improve, optimization-method integration, partition separation, candidate diffs/population, proposal review, activation identity/expiry/retry validation, application transaction port. - Closure path: external/fresh evidence → candidate generation/search → independent final-test comparison → review/activation → application write → later runtime uses changed capability. - Boundary reachability: these are public runtime APIs, but documentation explicitly preserves caller/application composition boundaries. - Why this is / is not agent-owned: the adaptation constructor is first-party and function-specific, while decisive domain adaptation/adoption remains composition-dependent. - Evidence: docs/improve.md; docs/learning-flywheel.md. - Basis: explicit + structural. - Confidence: medium-high. - Caveats: learning documentation explicitly says the complete process is not itself a demonstrated standalone learner; constructor credit does not assume that closure.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no qualifying first-party identity / ultimate-policy function established within the assessed runtime boundary. - Disturbance / variety regulated: identity-level or constitutional-policy disturbance is not established. - Decisive decision or feedback right: no qualifying ultimate-policy decision right is established. - Decision owner: none identified for an S5 function inside the assessed operating boundary. - Supporting / enforcement mechanisms: profiles, permissions, resource constraints, human review, and activation authorization exist but are execution/adaptation controls rather than an identity organ. - Closure path: no path was found from an identity/ultimate-policy issue through legitimate ultimate authority and back into subsequent runtime operation. - Why this is / is not agent-owned: because no qualifying S5 function is established, autonomy is not graded. - Evidence: docs/improve.md; docs/architecture.md. - Basis: explicit absence after boundary review. - Confidence: high. - Caveats: ordinary human approvals, profile configuration, and repository governance are not treated as S5 by substitution.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/73639464547d22d8b6764245e02810b8ffa46601/assessments/tangle-agent-runtime.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 73639464547d22d8b6764245e02810b8ffa46601\">7363946 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"2\" data-assessment-at=\"2026-10-18T19:10:04Z\"><th scope=\"row\"><a href=\"https://github.com/henrik-me/agent-harness\" target=\"_blank\" rel=\"noopener\">Henrik Agent Harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>2</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-18\">2026-10-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/henrik-me/agent-harness/tree/9168fa451b69c5d53b961ab5c805b3067597ade4\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 9168fa451b69c5d53b961ab5c805b3067597ade4\">9168fa4 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Produce substantive bounded changes and reviews in consumer software work through distinct model-backed contributors, and source-connected Copilot PR analysis. - Disturbance / variety regulated: Task-specific source/edit choices, unexpected actual code state, review findings and failure/repair feedback. - Decisive decision or feedback right: In the supported model-operated consumer mode, each contributor model chooses content of its scoped implementation or critique; GitHub Copilot chooses PR review findings from the actual current PR head. - Decision owner: Externally provided model agents acting under first-party scoped briefing and PR-review invocation; human/operator chooses the task and final merge, not the agent&#39;s substantive code/review response. - Supporting / enforcement mechanisms: harness dispatch emitted canonical prompt and owned-file scope, WORKBOARD.md, clickstop plan, real GitHub PRs, reviewer model allowlists and managed review gate checks. - Closure path: Consumer work/PR requirement → orchestrator supplies bounded first-party briefing or CLI requests Copilot reviewer → model performs implementation or PR review → changed files/review findings returned to the consumer PR/workboard → further correction and submission. - Boundary reachability: harness init/sync installs the model-enabled process instructions; harness review explicitly performs the GitHub reviewer request/poll rather than only drawing an agent diagram. External agent host/Copilot authorization must be configured; CLI-only mode has no model executor. - Why this is / is not agent-owned: Model-backed specialists and reviewer choose substantive decisions; deterministic Node tooling cannot derive their implementation or review findings without the model. This is an A mode only in the declared connected model-operated consumer cell, not for a standalone Node CLI. - Evidence: model roles and parallel work, subagent briefing and output, review execution path, real Copilot review request/poll. - Basis: First-party consumer operating contract plus executable external model reviewer integration. - Confidence: Medium source-structural; distinct implementer execution depends on external agent host not bundled. - Caveats: GitHub reviewer credentials, model quality, independent coding success and a complete live adopter project were not demonstrated. No autonomous execution claimed for the CLI itself.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: Prevent destructive conflicts among parallel operational contributors and overlapping currently active work claims before they affect other S1 outcomes. - Disturbance / variety regulated: Concurrent specialists silently overwriting one another&#39;s files and two orchestrator work claims racing for an already occupied coordination slot. - Decisive decision or feedback right: Establish disjoint per-agent editable file scopes and disallow a second active work claim for one owner unless deliberately transferred/taken over. - Decision owner: The parent orchestrator or operator decides actual task partition/scopes and takeovers; first-party deterministic CLI state and briefing constructors enforce/show preconditions, not autonomous mutual compromise. - Supporting / enforcement mechanisms: Explicit owned/read-only/do-not-touch briefing fields, no-commit worker discipline, WORKBOARD ownership rows, apply-time re-read/refusal, scoped clickstop branches. - Closure path: Parent receives parallel task candidates → declares separate file ownership in each emitted brief and claims a single active work slot → worker follows scoped briefing; conflicting claim is rejected, requiring reassignment before additional work proceeds → subsequent agent tasks operate on revised or nonoverlapping assignments. - Boundary reachability: harness dispatch builds emitted own/do-not-touch sections on every configured dispatch; claim directly checks the current WORKBOARD at plan and mutation time and fails closed for active owner collisions. These are delivered consumer-facing CLI commands and managed policy, not an aspirational slide. - Why this is / is not agent-owned: Concrete inter-worker lost-edit failure is documented in the source policy, and S2-specific interference is regulated through source-wired constructor/enforcement. The external orchestrator must pick the compromise, and the CLI does not independently detect all overlaps between distinct work files/agents. - Distinct S1 units: Independently model-operated specialist implementers assigned different concurrently active clickstop work and file scopes. - Inter-S1 disturbance: Two contributors can write one overlapping file and silently lose the earlier changes; the process source describes an observed lib/templating.mjs / lib/lock.mjs collision from parallel dispatch. - Attenuating coordination relation: Allocate exclusive writable sets per specialist and a single active work claim per owner; reject owner collision at apply-time. - Feedback into subsequent S1 behaviour: A conflicting owner work claim fails or a shared file becomes explicitly read-only for one worker; parent must rebrief/serialize/reclaim before launching the affected worker. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: These targeted mechanisms mitigate a stated inter-contributor lost-edit race and concurrent work-claim collision. Generic passing of a task ID or state alone is not counted. - Evidence: actual lost-edit incident and explicit file ownership, briefing file scope, claim collision check, apply-time recheck. - Basis: Shipped S2-specific coordination constructor with source-documented disturbance. - Confidence: Medium-high for the narrow fail-closed work-claim check and explicit overlapping-file procedure. - Caveats: The emitted brief does not compare all concurrent file scope declarations mechanically; adherence depends on the actual external orchestrator/worker.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3 / regulation: - State: C - Function: Assemble a whole-current delivery view and a bounded work-commitment lifecycle, allowing an external management actor to choose and revise active staffing, priorities and release/rework intervention. - Disturbance / variety regulated: Competing active clickstops, stale work, incomplete handoffs, unidentified worker ownership, current blocked dependencies and inconsistent PR closure. - Decisive decision or feedback right: Choose which planned clickstop to activate, assign its owner/branch, accept a failed review and instruct rework, decide whether to close/release completed work. - Decision owner: The source-prescribed external orchestrator or responsible human in the consumer project. The Node CLI gathers/checks workboard/current-state evidence and applies selected transitions; it does not autonomously choose among priority alternatives. - Supporting / enforcement mechanisms: WORKBOARD, harness status, harness claim, harness closeout, progress reports, single-active-work gate, review verdicts and CI merge controls. - Closure path: Whole current WORKBOARD and planned clickstop inventory → external manager identifies a current commitment, invokes claim/dispatch → workers return status/review evidence → manager decides correction/reallocation or closeout → first-party CLI updates active work and subsequent assignment context. - Boundary reachability: Consumer installation materializes the workboard and process docs; shipped claim/status/closeout commands read/write actual files and refuse inconsistent transitions. The core Node tool is a constructor for current-control decisions; the source does not auto-launch the orchestrator model. - Why this is / is not agent-owned: Model-coded management acts only when operated by an external agent host; removing that host leaves deterministic workboard plumbing but no discretionary portfolio negotiation. A positive C here identifies a specific delivered S3 control constructor, not automatic S3=A or generic workflow completeness. - Whole-system current view: The active/planned clickstop table and owner/branch/blocked metadata in WORKBOARD plus PR/review state and reporting, at the one consumer delivery-cell recursion. - Current-control decision scope: Active CS allocation/owner, constrained parallelism, failed review return and closeout of a project&#39;s current delivery commitments, not host-company staffing or long-term constitutional goals. - Evidence: claim current-cell view, claim mutation, closeout, orchestrator management role. - Basis: Specific first-party current-control observation, transition and return machinery, with externally owned discretionary S3 right. - Confidence: Medium source-structural. - Caveats: Human/LLM consumer actor is required; no standing self-running S3 agent, whole-system budget negotiator or parent-governed S3 (P) path is established by this source. Workboard alone does not count; the positive constructor depends on its wired claim/rework/closeout loop.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: Independently inspect producer claims against the actual PR head and return findings that alter acceptance/rework decisions. - Disturbance / variety regulated: Implementer overconfidence, stale review against an old commit, omitted blocking code defects or approval from a reviewer sharing the implementer&#39;s model context. - Decisive decision or feedback right: Model-based reviewer chooses a fresh Go/Needs-Fix and issue findings from reviewed PR evidence, independently of the producing actor; first-party review framework rejects reviewer-model conflicts and refuses to treat blocking findings as approval. - Decision owner: Independently invoked reviewer model (local rubber-duck when supplied, or GitHub Copilot PR reviewer) for factual/technical judgment, with first-party CI acting as enforcement. A model that also implemented the PR is barred by the configured separation rule. - Supporting / enforcement mechanisms: assertReviewerAllowed, model audit fields, actual PR HEAD and diff evidence, reviewer prompt, Copilot REST reviewer invocation, per-HEAD review log and managed review-gates.yml required checks. - Closure path: Implementer submits current source/PR → independent model reviews that head and identifies findings → computeVerdict returns No-Go/Needs-Fix on blocking output, logs exact reviewed SHA → review workflow blocks integration until a valid current-head review → orchestrator/worker reworks PR and requests a new round. - Boundary reachability: harness review first-party command genuinely requests Copilot reviewer through GitHub when review config enables it; review-gates.yml is shipped to consumers via init/sync and includes independent/attached evidence checks; source documents the reviewer dispatch as the normal content-PR gate. - Why this is / is not agent-owned: Reviewer model assesses producer output from separately obtained actual PR source, chooses critique and can force new work; deterministic log parsing and CI do not themselves own that independent judgment. - Claim being audited: Current implementer/subagent work is correct and ready to merge under its original clickstop acceptance criteria. - Ordinary reporting path: Worker completion report and PR author statements, branch status and routine task tests. - Complementary access path: Separate model reviewer analyzes actual PR current head/diff and required reading, with Copilot&#39;s independently attached GitHub review as a distinct channel. - Independence boundary: Different reviewer model from recorded implementers is enforced for local audit; Copilot is a separate GitHub review actor; primary evidence and head SHA are checked instead of recycling author summary alone. - Who acts on findings: First-party verdict and required checks withhold Go/merge evidence; supervised orchestrator triggers repairs and a new review round. - Evidence: review PR and independent-model gate, Copilot review and combined verdict, verdict logic, Copilot actual review, managed enforcement. - Basis: Explicit source-connected complementary reviewer judgment, distinct access and rework/block closure path. - Confidence: Medium-high for configured reviewer-enabled consumer mode; actual real PR review not replayed in this isolated assessment. - Caveats: Without GitHub authentication, enabled review checks and a responding reviewer, the model audit is not executable; source review is not a measured guarantee that Copilot detects all errors. Optional manual-only mode should not be conflated with autonomous reviewer operation.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: Scan external changes with a prospective model, develop options for changing future delivery-cell capability and return chosen adaptation to current control. - Disturbance / variety regulated: Changes in future tooling, supported environments, dependencies or customer delivery needs requiring a changed organizational capability rather than one repaired work item. - Decisive decision or feedback right: No shipped first-party externally prospective adaptation judgment and closed option-to-capability feedback right found. - Decision owner: Not established: harness upgrade compares a user-specified target Git ref deterministically, while harvest lists stale existing learning entries for later operator disposition. - Supporting / enforcement mechanisms: Upgrade dry-run diff, version pin and managed sync, LEARNINGS.md harvest, clickstop planning, changelog and maintenance rules. - Closure path: No first-party model of external future conditions that selects among capability change options, returns the prospective decision to S3, and updates later operational capacity without an externally authored plan. - Why this is / is not agent-owned: Upgrade preview and manual version application can change installed files, but the candidate ref and adoption judgment are supplied from outside, not selected through a shipped strategic prospective loop; stale-learning surfacing is retrospective operational improvement. - Evidence: upgrade takes specified ref and previews only, harvest stale items, model/role process configuration. - Basis: Bounded negative at first-party installed/CLI paths, not universal impossibility for custom consumers. - Confidence: Medium; human-managed downstream process evolution can be built from these primitives but is not itself source-closed S4. - Caveats: Consumer humans may perform strategic adaptation; the source does not warrant crediting that unobserved higher-recursion function.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: Resolve legitimate ultimate-policy/identity disputes over the consumer delivery cell&#39;s enduring mission and reconcile current versus future orientations. - Disturbance / variety regulated: Conflicting enduring purposes, permissible changes of identity, constitutional operating constraints or ultimate authority. - Decisive decision or feedback right: Not established by the first-party shipped process. User approval gates concern task-plan/implementation details or acceptance of a code/review change, not a reconstructable constitutional adjudication path. - Decision owner: No source-connected S5 ultimate-policy actor is evidenced; the adopter or project owner remains external higher recursion. - Supporting / enforcement mechanisms: INSTRUCTIONS, CODEOFCONDUCT, CONVENTIONS, review rulesets, workboard approval policy, optional owner override, credentials and repository settings. - Closure path: No identity-level issue → legitimate constitutional authority → authoritative decision → re-governed ongoing operations path established in first-party artifact. - Why this is / is not agent-owned: Managed policy files and approvals constrain delivery, but do not transform their configured owners into a standing S5 entity. Model roles cannot independently rewrite legitimate identity. - Evidence: operating approval context, review policy, workboard gate. - Basis: Bounded negative following inspection of permission, process governance and approval mechanisms. - Confidence: Medium-high in this assessed recursion. - Caveats: A consumer can attach genuine external S5 institution; it is not first-party authority supplied by the library.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/12eb45991ddd86b008d65053dbcf2dcfbce61ac3/assessments/he/henrik-agent-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 12eb45991ddd86b008d65053dbcf2dcfbce61ac3\">12eb459 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-10-02T23:59:44+03:00\"><th scope=\"row\"><a href=\"https://github.com/prasenjeet-symon/ogcode\" target=\"_blank\" rel=\"noopener\">Ogcode</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-02\">2026-10-02</time></td><td class=\"review-ref\"><a href=\"https://github.com/prasenjeet-symon/ogcode/tree/b9077a0fcca60195da4426b3f733933b533be705\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision b9077a0fcca60195da4426b3f733933b533be705\">b9077a0 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: produce repository-facing software outcomes through open-ended model/tool coding action. - Disturbance / variety regulated: heterogeneous code structure, incomplete implementation details, syntax/build/test failures, repository state, tool output, external documentation, context limits and changing user requirements encountered during implementation. - Decisive decision or feedback right: decide what project evidence to inspect, which coding/tool action to take, how to respond to returned failures/evidence, what implementation satisfies the assigned outcome and when local work is complete. - Decision owner: model-backed BuildAgent in interactive work and model-backed TaskAgent in each plan worktree. - Supporting / enforcement mechanisms: tool registry; repository maps/search/read/edit/write/bash; syntax checks; provider adapters; permissions; sessions; compaction/memory; worktrees and git; cancellation/timeouts. - Closure path: software goal/task description plus project context → agent selects action/tool → tool/environment result returns into the same agent loop → agent revises implementation or verifies/finishes → repository-facing result is produced. - Boundary reachability: BuildAgent is the normal interactive mode; TaskAgent is constructed by the standard plan/task execution path and runs the shipped coding loop in its worktree without adopter-authored orchestration. - Why this is / is not agent-owned: removing the model-backed Build/Task actor while retaining tools, worktrees, stores and permission machinery removes the task-specific software-engineering judgment. - Evidence: internal/agent/agent.go; internal/agent/loop.go; internal/server/taskroutes.go; README.md. - Basis: explicit + structural. - Confidence: high. - Caveats: external model inference and GitHub remote service behavior are dependencies; the credited loop/control composition is first-party Ogcode.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: prevent destructive interference and merge conflict among parallel implementation S1 workstreams by deciding file ownership/dependency relations before execution and feeding those relations into task scope/order. - Disturbance / variety regulated: independently executing TaskAgents can otherwise modify overlapping files from parallel branches, creating incompatible patches/merge conflicts; dependent implementation can also run before prerequisite changes are present. - Distinct S1 units: separate TaskAgent sessions executing different implementation tasks in distinct git worktrees/branches. - Inter-S1 disturbance: overlapping parallel file mutation can produce competing patches at integration time; premature dependent execution can act on a repository state missing predecessor work. - Attenuating coordination relation: BreakdownAgent must assign each file to exactly one parallel workstream and add a dependency whenever two tasks need the same file. It also defines linear dependencies reflecting implementation prerequisites. The runtime then isolates tasks in worktrees and executes dependencies only after predecessor integration. - Feedback into subsequent S1 behaviour: BreakdownAgent&#39;s task descriptions/dependencies become the authoritative TaskAgent prompts and task records; the chosen graph determines whether a task starts concurrently or waits, which branch/worktree it sees, and which files it is instructed to modify. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the first-party breakdown prompt explicitly names the concrete shared-file merge-conflict disturbance and requires file ownership/dependency decisions to attenuate it. Worktrees and dependency scheduling enforce that selected coordination relation rather than merely moving work between agents. - Decisive decision or feedback right: choose the task-specific partition of files/workstreams and the dependency relation needed to avoid cross-worker conflict while preserving safe parallelism. - Decision owner: model-backed BreakdownAgent. - Supporting / enforcement mechanisms: structured submittaskbreakdown; task dependency records; per-task worktrees/branches; chain branches; dependency readiness checks; atomic task claims; serialized git metadata mutation; automatic dependent startup after predecessor integration. - Closure path: locked plan/repository evidence → BreakdownAgent identifies scopes/dependencies under explicit anti-conflict rules → structured task graph is stored → server creates isolated worktrees and schedules according to that graph → TaskAgents receive scoped descriptions and predecessor state → later S1 operation follows the selected coordination. - Boundary reachability: BreakdownAgent, breakdown tool and plan/task materialization are invoked automatically by the standard locked-plan mode; no consumer-authored coordinator is needed. - Why this is / is not agent-owned: removing BreakdownAgent leaves deterministic mechanisms capable of enforcing a supplied graph, but removes the discretionary, task-specific choice of which files/workstreams should be parallel versus ordered. - Evidence: internal/agent/breakdown.go; internal/agent/agent.go; internal/tool/breakdown.go; internal/server/taskroutes.go. - Basis: explicit + structural. - Confidence: high. - Caveats: worktree/dependency enforcement itself is deterministic; autonomy is assigned to the BreakdownAgent&#39;s organizational partition decision, not to git or the scheduler.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: give the legitimate operator a whole-plan current view and authority to intervene in active implementation commitments on behalf of the current software-delivery whole. - Disturbance / variety regulated: a plan may contain pending, blocked, running, failed and completed tasks; a current TaskAgent can stall, take a wrong path, fail, need retry or need operator-directed interruption while other plan commitments continue. - Whole-system current view: the first-party task board groups every task in the active plan by current status, shows total/done/running/failed/pending counts, dependency eligibility and per-task branch/session/PR state. - Current-control decision scope: start one eligible task or all eligible tasks; inspect a running task&#39;s live agent session; abort that running session; mark current work complete/failed where appropriate; retry failed work from a clean task state. - Decisive decision or feedback right: choose which currently eligible commitments are started and when a current task session should be interrupted/retried/failed as part of supervising the active plan. - Decision owner: human/operator at the parent recursion. - Supporting / enforcement mechanisms: plan/task stores; task-board projections; task/session routes; server running-loop registry; context cancellation; dependency scheduler; worktree cleanup/retry; SSE/bus status updates. - Closure path: task board/current session exposes whole-plan current state → operator selects start/intervention/retry or abort → first-party API mutates task state or cancels the registered task session loop → task/plan events and dependency eligibility update → subsequent current execution changes. - Boundary reachability: the browser plan/task board and task-execution session are standard product surfaces; TaskAgent loops are registered in the same server running map consumed by the generic first-party session-abort endpoint. - Why this is / is not agent-owned: BreakdownAgent selects the initial coordination graph but does not receive a live whole-plan control loop. Runtime auto-start is deterministic enforcement of the frozen dependency graph. The discretionary current-control mode established in the frozen product belongs to the operator. - Evidence: web/src/pages/plan-tasks.tsx; web/src/pages/task-execution.tsx; internal/server/taskroutes.go; internal/server/sessionroutes.go. - Basis: explicit + structural. - Confidence: high. - Caveats: this is a parent/operator supervisory mode, not autonomous S3. The deterministic dependency scheduler and automatic completion transitions do not themselves own discretionary whole-system current-control judgment.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party complementary audit loop was established that independently challenges implementation claims and returns a distinct audit judgment into current control. - Disturbance / variety regulated: implementation agents can be wrong about the correctness/completeness of their own changes, but the frozen standard distribution does not package a separate reviewer/evaluator role or audit gate with complementary evidence access. - Claim being audited: no standard first-party independent-audit claim/route was established. - Ordinary reporting path: BuildAgent/TaskAgent implement changes and are themselves instructed to run syntax/build/test/lint verification before declaring completion. - Complementary access path: none established as an audit function. The generic task tool can spawn a clean-context read-only investigator over code/web evidence, but its shipped contract is broad investigation/context offload rather than independent review of producer claims, and no standard reviewer role/accept-correct loop is wired around task completion. - Independence boundary: no material audit boundary is established beyond optional generic investigation. - Who acts on findings: no standard independent-audit finding/closure path established. - Decisive decision or feedback right: none established for S3. - Decision owner: not established. - Supporting / enforcement mechanisms: self-verification in coding prompts; read-only TaskTool investigation; syntax checker; builds/tests; git/PR artifacts. - Closure path: not applicable; no standard complementary auditor judgment is returned as a distinct control input. - Boundary reachability: not applicable for a positive path. - Why this is / is not agent-owned: ordinary tests and the implementer&#39;s own verification are the production path, while generic clean-context investigation is not packaged as an audit function in the frozen distribution. - Evidence: internal/agent/agent.go; internal/tool/task.go; internal/server/taskroutes.go. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: an operator or BuildAgent could formulate a review-like prompt for the generic read-only child, but generic subagent expressiveness is not treated as a standard-distribution S3 audit loop.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party outside-and-then loop was established that senses external/future change, develops organizational adaptation options and returns a selected adaptation into present capability. - Disturbance / variety regulated: external documentation/search, prior project decisions, model/tool availability and persistent memory can influence current software work, but none forms a first-party prospective adaptation cycle at the selected organization boundary. - Decisive decision or feedback right: none established for S4. - Decision owner: not established. - Supporting / enforcement mechanisms: deepsearch and page fetching; PlanAgent; NoteAgent; session/project memory recall; MEMORY.md; skills/MCP/model configuration; compaction; persistent sessions and archived plans. - Closure path: not applicable; no external/future distinction → adaptation-option development → selected persistent capability/strategy change → return to current S3/capability loop was found. - Why this is / is not agent-owned: PlanAgent plans current requested software, recall restores past operational context, and search answers present questions. These paths do not establish prospective organizational adaptation merely because they contain research, learning or persistence. - Evidence: README.md; internal/agent/agent.go; internal/tool/memoryrecall.go; internal/tool/projectmemoryrecall.go; internal/agent/memorymd.go. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: the README contains a broader future computer-agent vision; intake explicitly excludes those roadmap claims from current-state evidence.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S5 / identity: - State: P - Function: carry legitimate project-owner standing instructions/rules into every relevant Ogcode agent context so later software work remains governed by project-level policy. - Disturbance / variety regulated: coding/planning/task agents can otherwise diverge from repository architecture, conventions, risk boundaries or durable owner instructions across sessions/worktrees. - Identity / ultimate-policy issue: which durable project rules, priorities and behavioral constraints legitimately govern Ogcode&#39;s work in the selected repository. - Ultimate authority in each claimed mode: Parent (P) — the legitimate project owner/editor owns project AGENTS.md / AGENT.md instruction content. No autonomous agent-owned identity/ultimate-policy mode is established. - Return-to-operation path: Ogcode discovers owner-authored instruction files from root to current project directory, preserves root-to-leaf precedence, loads their text into the agent system-prompt construction and thereby governs later Build/Plan/Task execution in that project. - Decisive decision or feedback right: decide the durable project-level instructions and precedence that should constrain future agent operation. - Decision owner: human/project owner at the parent recursion. - Supporting / enforcement mechanisms: instruction-file discovery/loading; root-to-leaf ordering; prompt block rendering/escaping; system prompt builder; ordinary file/version-control persistence. - Closure path: project-level policy issue → legitimate owner changes AGENTS.md/AGENT.md → Ogcode reloads project instructions for agent execution → instructions enter system context → subsequent software operation is governed by the returned policy. - Boundary reachability: AGENTS.md/AGENT.md loading is first-party runtime code invoked by the standard agent prompt construction; it is not a contributor-only plugin or external wrapper. - Why this is / is not agent-owned: model agents consume the standing instructions but do not receive a first-party mechanism making their self-authored policy legitimate ultimate authority; ownership remains with the project authority that supplies the files. - Evidence: internal/agent/agentmd.go; internal/agent/loop.go; README.md. - Basis: explicit + structural. - Confidence: high. - Caveats: permission prompts and ordinary task/plan approval are operational controls and are not used as S5 evidence; S5 is limited to durable project-recursion policy returned through the project instruction surface.\">P</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/84c26bb06c83f644c72a156d8214cfcb5a19bcf8/assessments/ogcode.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 84c26bb06c83f644c72a156d8214cfcb5a19bcf8\">84c26bb &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-17T03:12:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/proliferate-ai/proliferate\" target=\"_blank\" rel=\"noopener\">Proliferate</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-16\">2026-09-16</time></td><td class=\"review-ref\"><a href=\"https://github.com/proliferate-ai/proliferate/tree/74e1178cf3ecfbfc3ffeb8321f82c4a9bfce620f\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 74e1178cf3ecfbfc3ffeb8321f82c4a9bfce620f\">74e1178 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: standard product sessions run native coding-agent harnesses that autonomously inspect, edit and execute work inside bounded task workspaces; child sessions can independently complete delegated scoped work and return results.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: first-party isolation, parent→child messaging and exact completion wakeups are conflict avoidance/delegation mechanisms. The pinned implementation does not provide an agent-owned mutual-adjustment loop that observes and dampens interference or oscillation among peer S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: the product control plane provisions workspaces, sessions and workflows, while a parent may supervise its own delegated children, but no distinct autonomous actor is given current-whole authority to regulate shared resources, commitments or priorities across the operational system. Scheduling/provisioning alone is not Beer S3.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: the first-party review runtime establishes an independent audit path. Review-only agents inspect trusted plan/code targets, are prohibited from modifying them, submit structured pass/critique results, and return findings to the parent session. The runtime can automatically iterate parent revision → trusted recapture → fresh review round until pass or a configured round limit. This is a ready, agent-enacted complementary audit/feedback loop rather than a developer-supplied verifier primitive.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: recurring/event-driven workflows react to configured events and can run tasks such as triage or dependency updates, but the pinned distribution does not establish a persistent agent-owned external/prospective intelligence function that models environmental change and feeds adaptation into present control.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: harness choice, workflow definitions, reviewer configuration, permissions and review policy remain product/operator configuration. No first-party agent holds final authority over organizational identity, purpose or constitutional policy.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/ff74c380425fb7c8a9cee512289cdb428d74dbb1/assessments/proliferate.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit ff74c380425fb7c8a9cee512289cdb428d74dbb1\">ff74c38 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-10-18T04:20:15+03:00\"><th scope=\"row\"><a href=\"https://github.com/Darwin-Agent/HarnessX\" target=\"_blank\" rel=\"noopener\">HarnessX</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-18\">2026-10-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/Darwin-Agent/HarnessX/tree/915520584c92cc35ed24aef1af17eec1d60c0b01\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 915520584c92cc35ed24aef1af17eec1d60c0b01\">9155205 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Conduct current user/evaluation task work by selecting available tools through the task agent and adapting next model actions after real tool execution observations. - Disturbance / variety regulated: New task/environment inputs, failing or successful real tools, edits/observations, unexpected model answers, session interruptions and capability budgets. - Decisive decision or feedback right: The configured model produces tool calls and subsequent decisions; source-owned RunLoop executes registered tool callbacks and inserts real results into task state/conversation; this changes next possible actions and the produced task result. - Decision owner: First-party HarnessX installed model-backed task agent using third-party inference through an explicit provider boundary. Tool registry/hooks and model budgets limit discretionary task actions. - Supporting / enforcement mechanisms: HarnessConfig, RunLoop, tool registry and ToolResultEvent, state/trajectory, hook processors, workspace and sandbox, cost guard and interruption/resume. - Closure path: Task → Harness.run → model-driven RunLoop → selected registered tool call → executable handler → ToolResultEvent appended to state → next model turn/action/final deliverable → task trajectory, used by evolution. - Boundary reachability: Shipped public Harness.run and provider configuration lead directly to runloop with actual tool registry execution and observation persistence. This is source-level production code, not just an interface or benchmark score. - Why this is / is not agent-owned: Tool choice and subsequent result-informed task continuation belong to the configured model-backed agent; process hooks and static restrictions are safeguards and do not stand in for autonomous task decisions. - Evidence: harnessx/core/harness.py; harnessx/core/harness.py; harnessx/core/runloop.py; harnessx/core/runloop.py; harnessx/core/runloop.py; harnessx/core/runloop.py; harnessx/core/runloop.py. - Basis: First-party model/tool/result closure in shipped operational runtime. - Confidence: High structural confidence; no external provider inference executed. - Caveats: Deterministic processor execution without a configured model is not by itself S1=A. External benchmark correctness is unverified.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No first-party disturbance-specific reciprocal coordination role across independently viable S1 operating units is established at this recursion. - Disturbance / variety regulated: Parallel evaluation tasks or agent subprocesses may share budgets, files and outputs; runtime processors and meta-agent write-scope gates constrain local conflicts rather than observing competing viable units. - Decisive decision or feedback right: Tool call/processor ordering, task timeout, separate round/config workspaces, and write-path gates block or sequence current work. There is no shipped S2 arbitration decision choosing mutual adjustments between independent S1 units from sensed interference. - Decision owner: Per-task RunLoop and static plugin/recipe configuration, external operator for parallelism; no legitimate standing S2 controller. - Supporting / enforcement mechanisms: Processor pipeline, workspace/sandbox isolation, write/read scopes, run/round files and configured evaluation concurrency. - Closure path: Tool tasks/rounds → isolated/sequenced execution → results; missing identified inter-S1 operational disturbance → agent-selected damping policy → returned reciprocal operating restrictions. - Why this is / is not agent-owned: Worker scheduling, output isolation and sandbox hardening are infrastructure, not an evidenced VSM S2-specific inter-unit interference regulator. - Evidence: harnessx/core/runloop.py; harnessx/core/runloop.py; harnessx/metaharness/processors/writescopegate.py; recipe/tb2evolver/run.py; harnessx/core/processor.py. - Basis: Bounded absence after testing parallel tasks, hooks, meta-agent workspace/write conflict surfaces. - Confidence: Medium-high for frozen first-party sample modes. - Caveats: A multi-tenant adopter could use plugins to implement such policies; hypothetical external implementations do not count.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No owner makes binding whole-current priority/resource/commitment choices over separate ongoing viable S1 divisions. - Disturbance / variety regulated: Failed evaluations, incomplete rounds, step/cost limits and rejected harness edits affect current experiment progress; no multi-division current operating commitments are modeled. - Decisive decision or feedback right: Recipe controller selects fixed benchmark task sets and configured round order; meta-agent proposes harness redesign, the validator rejects invalid candidates, and acceptance applies to future model-agent configs. There is no first-party global portfolio operating priority decision with S1 management intervention. - Decision owner: External experiment operator and code-configured round runner; local agent and meta-agent for task/design choices, not an accountable whole-current S3 manager. - Supporting / enforcement mechanisms: Round state, currentconfig, task eval logs, budgets, postflight validation, recovery/fallback for the experiment. - Closure path: Configured run → eval and improvement → next round; missing whole-current multi-unit status → legitimate obligations/resource tradeoff decision → binding cross-unit current action return. - Why this is / is not agent-owned: Meta-agent evolves capability across rounds (S4 here), rather than holding a standing current-control mandate for multiple separate viable S1 operating cells. - Evidence: recipe/tb2evolver/run.py; recipe/tb2evolver/run.py; recipe/tb2evolver/run.py; recipe/gaiaevolver/run.py; harnessx/metaharness/validateworkflow.py. - Basis: Tested meta-agent, benchmark controller and task manager candidates against S3 scope. - Confidence: Medium-high. - Caveats: Human research team/resource management or downstream customer program control are not in the first-party running harness.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No independently sourced complementary audit of a standing S3&#39;s operational claims with returned corrective management authority. - Disturbance / variety regulated: Unfit candidate configs, invalid contracts, failing replay and incorrect task results are detectable; evidence quality and safety are safeguarded but not used to audit whole-current management reporting. - Decisive decision or feedback right: EvolveValidator checks canonicalization, contract, replay and policy and may reject a proposed evolved config. Benchmark evaluator/LLM judge may score task output; a rejection returns to next harness edit or run fallback, not to any legitimate S3 owner required to correct current organizational commitments. - Decision owner: Validation and replay implementation plus externally configured benchmark grader; no separate organizational audit with independent direct operating-fact access and governing S3 corrective return. - Supporting / enforcement mechanisms: Validation report, changeset, replay smoke check, novelty/evidence gate, cross-round journal and per-task scoring. - Closure path: Proposed config → validity/replay/policy check → permit or reject for next experiment. Missing independent observation of S3 current-performance claim → challenge → binding S3 remedy applied across S1 units. - Why this is / is not agent-owned: A separate technical validation gate can be effective without being S3: source shows config/test validity and task scoring, not a complementary management reality-check function with its own return. - Evidence: harnessx/metaharness/agent.py; harnessx/metaharness/validateworkflow.py; harnessx/metaharness/validateworkflow.py; harnessx/metaharness/validateworkflow.py; harnessx/metaharness/validateworkflow.py; harnessx/metaharness/validateworkflow.py; harnessx/metaharness/replay.py. - Basis: First-party strongest audit-candidate source path inspected and bounded to config/task checking. - Confidence: Medium-high. - Caveats: External independent benchmarks are not automatically first-party independent organizational auditor; their scoring policy cannot be borrowed.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: Use encountered external task/evaluation outcomes to autonomously redesign future agent-harness capabilities, validate new viable options and commit an accepted changed configuration for later operating rounds. - Disturbance / variety regulated: Past harness may fail unknown future tasks; patterns in new environments and actual trajectories reveal deficiencies in instructions, processors, tools, and resource/safety boundaries that motivate future changes. - Decisive decision or feedback right: The model-backed MetaAgent diagnoses prior task trajectories and autonomously writes candidate changed HarnessConfig plus prompt/processor implementations. EvolveValidator enforces source-owned validity/contract/replay/novelty gates; the shipped multi-round recipe promotes a valid candidate into durable round config and sets it as currentconfig for the next evaluator/task-agent execution. - Decision owner: Configured MetaAgent model for proposed future capability and technical validation controller for admission; the first-party executable evolver recipe is the accepted-change authority within the explicitly bounded experiment. No claim of wider business approval. - Supporting / enforcement mechanisms: Trajectory collection and benchmark feedback, journal of hypotheses/round history, model-backed config editor, write scope and budget, canonicalization/contract/replay checks, output config plus promoted round state/resume file. - Closure path: External evaluation tasks and failures → task trajectories and cross-round context → MetaAgent model diagnoses/generates alternative future prompt/tools/processors → EvolveValidator checks new config → recipe promoteroundoutput and updates persisted lastoutputconfig / currentconfig → next round uses changed executable HarnessConfig and creates fresh feedback. - Boundary reachability: recipe/tb2evolver/run.py is a first-party executable: MetaAgent(...) constructed at line 635, each iteration reads current trajectories then calls metaagent.evolve at line 710, adapter promoteroundoutput at 718, state persists lastoutputconfig at 746, and currentconfig=promotedconfig at 751. Separate GAIA recipe writes currentconfig=candidatecfg after validation; no optional custom external adopter glue is needed. - External distinction: Task benchmark/environment outcomes are observed from separately executed tasks and actual candidate trajectories, not inferred from static configuration alone. They include failures and task variation across rounds; benchmark grader policy and provider internal operations stay outside HarnessX ownership. - Future / prospective distinction: The MetaAgent modifies reusable prompt/processor/tool harness configuration for following, distinct evaluation tasks and rounds, rather than merely choosing the best answer to the present user&#39;s one request. Round state and journal deliberately carry changed capability forward. - Adaptation option generated: A model-authorized configuration editor proposes new prompt templates, hook processors, configured tool paths and other allowed harness levers from observed failure patterns. Novelty and replay checks distinguish viable alternatives from a repeated/no-op or invalid modification. - Path back into current capability / S3: After successful source-owned postflight, the recipe promotes the new config path, records it in persisted run state and loads that same config as currentconfig for subsequent ordinary Harness.run task evaluation. This closes directly into the next S1 operating capability at the harness-improvement recursion; no independent organization-wide S3 is assumed. - Why this is / is not agent-owned: Model selection of what harness should become, based on external task evidence, combines with first-party validation and actual promotion into later execution. This is a concrete prospective, executable capability loop and not only a memory/summary or evaluation score. - Evidence: harnessx/metaharness/agent.py; harnessx/metaharness/agent.py; harnessx/metaharness/agent.py; harnessx/metaharness/validateworkflow.py; harnessx/metaharness/journal.py; recipe/tb2evolver/run.py; recipe/tb2evolver/run.py; recipe/tb2evolver/run.py; recipe/tb2evolver/run.py; recipe/tb2evolver/run.py; recipe/tb2evolver/run.py; recipe/gaiaevolver/run.py; recipe/gaiaevolver/run.py. - Basis: Independent first-party S4 option/change/admission and installed next-round loop; positive limited to configured, source-wired harness-improvement experiment. - Confidence: Medium-high for source reachability and capability adoption, not benchmark effectiveness. - Caveats: The validator can reject proposed configs and produce no new capability; not every iteration improves scores. Promotion applies to experimental harness config rather than a managed external production service or approved enterprise deployment. User supplies experiment scope and models. First-party recipe may deliberately accept a valid but not empirically improved config; S4=A here indicates a future-capability adaptation mechanism, not guaranteed selection of a better policy.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No system-owned ultimate legitimate purpose/identity policy arbiter adjudicates what goals the harness-improvement organization must pursue. - Disturbance / variety regulated: Allowed tool/build paths, model cost, replay bounds and evidence rules constrain experiments but do not legitimate a changed institutional purpose. - Decisive decision or feedback right: Human selects benchmark/task pool/provider, allowed write roots and budgets; EvolveValidator and gates permit/reject one future config according to those preset criteria. No S5 authority changes the ultimate ethical/purpose contract across the system. - Decision owner: External adopter/research experiment operator for goals, data rights and provider choices; first-party validation engines for local code safety, not final governing mission. - Supporting / enforcement mechanisms: Meta-agent write scope, run cost/timeout, canonical config schema, validation/novelty policy, benchmark setup and repo maintenance/license. - Closure path: Preset experiment objective → candidate design/replay → future config. Missing conflicting ultimate values/identity interpretations → legitimate final authority decision → enforceable mission/purpose return. - Why this is / is not agent-owned: Source technical acceptance of one capability modification (S4) is narrower than authorizing the whole organization&#39;s ultimate identity and purpose (S5). - Evidence: harnessx/metaharness/agent.py; harnessx/metaharness/agent.py; harnessx/metaharness/validateworkflow.py; harnessx/metaharness/processors/writescopegate.py; recipe/tb2evolver/run.py. - Basis: First-party config-policy, safety and external institutional-right boundary inspected. - Confidence: Medium-high at declared recursion. - Caveats: The external university/company/deployer may own legal purpose; this package does not instantiate such a VSM owner.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/4143efce3ef5f626dc3211866f7cd1409773ec6d/assessments/harnessx.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 4143efce3ef5f626dc3211866f7cd1409773ec6d\">4143efc &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-09-24T22:25:19Z\"><th scope=\"row\"><a href=\"https://github.com/Growth-Circle/cadis\" target=\"_blank\" rel=\"noopener\">C.A.D.I.S.</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-25\">2026-09-25</time></td><td class=\"review-ref\"><a href=\"https://github.com/Growth-Circle/cadis/tree/52c55854b1abbcda82839b7a934cbdb16a69b635\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 52c55854b1abbcda82839b7a934cbdb16a69b635\">52c5585 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: execute user objectives through a model-driven tool/action loop that receives environment/tool observations and chooses subsequent operational action until completion. - Disturbance / variety regulated: request ambiguity, workspace/file/git/shell state, tool results, provider responses, failed actions and intermediate evidence that changes the next useful operational step. - Decisive decision or feedback right: choose which available tool/action to invoke, its arguments, whether further action is needed and the final operational response within configured safety/step bounds. - Decision owner: the model-driven CADIS agent running through the daemon&#39;s first-party generation/tool loop. - Supporting / enforcement mechanisms: provider adapters, parsetoolcalldirectives, native tool registry, workspace grants, policy engine, approvals, session/step limits, persistence and daemon event streaming. - Closure path: request enters cadisd → routed agent/model generates a tool directive or response → daemon executes the selected tool under policy/workspace controls → tool results are placed into a follow-up prompt → model chooses the next action or completes → result returns to the caller/environment. - Boundary reachability: ordinary message.send through the shipped daemon executes this first-party loop; no downstream organizational actor must be supplied to obtain model/action/feedback closure. - Why this is / is not agent-owned: policy, grants and bounds can reject or constrain choices, but they do not predetermine the substantive tool/action sequence. Removing the model actor removes the ordinary operational decision path. - Evidence: crates/cadis-daemon/src/main.rs; crates/cadis-core/src/lib.rs; README.md. - Basis: explicit + structural - Confidence: high - Caveats: direct client commands and deterministic policy/approval branches also exist. A is based on the standard model-owned tool/action path, not on every request transition being autonomous.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate interference among distinct concurrently active CADIS operational agents/workers by isolating project mutations and bounding shared worker concurrency. - Disturbance / variety regulated: parallel coding units can corrupt or overwrite the same working tree, while unbounded fan-out can consume shared daemon capacity and delay peer work. - Decisive decision or feedback right: choose/revise the cross-S1 isolation and shared-concurrency regime that determines where a coding worker may mutate files and whether another worker may begin now or must wait. - Decision owner: no autonomous first-party S2 actor owns that regime. The standard daemon supplies the function-specific worktree/queue relation and deterministically enforces parent/configured limits, leaving revision of the regime outside autonomous S2 ownership. - Supporting / enforcement mechanisms: per-worker worktree intent and metadata, Git worktree creation, workspace/grant checks, worktree-local worker command cwd, maxconcurrentworkers, global running-worker count, queued worker state and slot-release/start logic. - Closure path: multiple S1 tasks enter parallel worker execution → daemon allocates project work into separate owned worktrees and counts current running workers → excess workers remain Queued and isolated workers operate on separate branches/paths → freed slots start waiting workers and their subsequent execution proceeds under the isolated context. - Boundary reachability: worktree-backed worker operation and global worker admission are shipped daemon/core paths at the pinned revision; callers do not need to implement their own isolation or worker queue. - Why this is / is not agent-owned: the disturbance and attenuation relation are first-party and specific to cross-unit interference, but isolation/admission outcomes are mechanically derived from configured policy rather than selected by an autonomous coordinating model. This supports C, not A. - Evidence: crates/cadis-core/src/lib.rs; docs/10RISKREGISTER.md; README.md. - Basis: explicit + structural - Confidence: high - Caveats: generic @agent routing and child-agent spawning are not credited as S2 by themselves. Positive credit rests on the documented parallel-edit/resource disturbances and the first-party isolation/backpressure relation. - Distinct S1 units: two or more separately routed/spawned model-driven agents/agent sessions executing operational tasks inside the same cadisd, including coding tasks represented by daemon-managed worker records. - Inter-S1 disturbance: simultaneous project mutations can conflict on the same repository state, and concurrent worker fan-out can exceed shared worker execution capacity even when each task is locally valid. - Attenuating coordination relation: CADIS assigns project workers separate Git worktrees and applies a daemon-wide maximum number of running workers, holding excess work in Queued state. - Feedback into subsequent S1 behaviour: the owned worktree becomes the worker&#39;s execution context/cwd for validation and artifacts, while queued workers do not begin until a shared slot is released; both relations change where or when each S1&#39;s next operation occurs. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the credited mechanisms are explicitly aimed at cross-agent file-conflict and aggregate fan-out disturbances, not merely at transporting messages, naming specialists or ordering a task graph.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A(P) - Function: maintain a current organization-wide view of agent commitments and use it to allocate/change present operational work, with an additional legitimate parent/operator intervention mode. - Disturbance / variety regulated: duplicated or poorly allocated agent work, changing agent/session status, current task commitments, runaway/unwanted current activity and aggregate worker pressure can make the daemon&#39;s present operation incoherent or exceed current capacity. - Decisive decision or feedback right: autonomous mode — decide from current all-agent state whether to create a new child agent and assign it a task; parent mode — inspect the current roster and terminate an agent or cancel a session, removing associated current commitments/workers from later operation. - Decision owner: autonomous mode — the main CADIS model actor receiving first-party current runtime state; parent mode — the legitimate self-hosting operator using shipped CLI/HUD/protocol controls. - Supporting / enforcement mechanisms: orchestratorawarenesscontext(), agent/session registries and sorted snapshots, recent-session task/step summaries, bounded model-driven [SPAWN] parsing, spawn limits, global worker scheduler, agent.list, agent.kill, session.cancel, persistence and cancellation propagation. - Closure path: current agent roster/session state is assembled → injected into the main agent&#39;s prompt → main model selects a new child role/task when current organization needs it → runtime creates the child and task-bearing session → subsequent organization state includes the changed commitment. In parent mode, roster inspection → kill/cancel request → agent/session and non-terminal associated worker cancellation → subsequent live operation reflects the intervention. - Boundary reachability: whole-agent awareness and model-driven child spawning are standard first-party runtime paths; parent list/kill/cancel operations are stable shipped protocol/CLI/HUD surfaces. - Why this is / is not agent-owned: the main actor receives whole-organization current state rather than only one delegated task and autonomously changes current commitments. Deterministic spawn/worker limits constrain that authority but do not choose the child task. The parent path is separately owned by the operator, producing the (P) modifier. - Evidence: crates/cadis-core/src/lib.rs; docs/29PROTOCOLFREEZE.md; crates/cadis-cli/src/main.rs. - Basis: explicit + structural - Confidence: medium-high - Caveats: ordinary delegation is not credited as S3 by itself. The positive autonomous mapping depends specifically on the main agent&#39;s injected whole-roster/recent-session state plus its live model-owned commitment-creation path. Worker concurrency limits are supporting current-control enforcement, not the reason for A. - Whole-system current view: orchestratorawarenesscontext() enumerates the current agent roster with status, specialist and latest task and also includes recent agent sessions with state and step/budget progress; this generated state is injected into the main orchestrator prompt. - Current-control decision scope: autonomous creation/allocation of new child-agent commitments in response to current organization state, plus parent termination/cancellation of existing live commitments; daemon worker admission additionally constrains concurrent execution.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party complementary audit path is established for the declared CADIS operating boundary at the pinned revision. - Disturbance / variety regulated: not established. - Decisive decision or feedback right: not established. - Decision owner: none established. - Supporting / enforcement mechanisms: optional reviewer/tester specialist roles, worker validation commands/test-report artifacts, patch-apply preflight, policy checks, approvals, logs and lifecycle events. - Closure path: not established as S3. These paths validate ordinary outputs or expose ordinary evidence but do not establish a materially independent complementary challenge of an S1/S3 operational claim with a required corrective return. - Why this is / is not agent-owned: a role named Reviewer can be spawned/routed, but it uses the common agent contract and is not packaged as a mandatory complementary audit owner with distinct evidence access/authority. Deterministic validation/preflight is routine production QA/integrity control. - Evidence: docs/standards/10AGENTSTANDARD.md; crates/cadis-core/src/lib.rs; docs/29PROTOCOLFREEZE.md. - Basis: explicit + structural absence - Confidence: medium-high - Caveats: a downstream organization can deliberately instantiate a reviewer with different workspace/test access. That would be a separate system-in-focus and does not upgrade the standard CADIS distribution here.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party outside-and-then adaptation loop is established for the declared CADIS operating boundary at the pinned revision. - Disturbance / variety regulated: not established as prospective adaptation. - Decisive decision or feedback right: not established. - Decision owner: none established. - Supporting / enforcement mechanisms: persistent memory records/capsules, workspace/project facts, correction/procedure memory kinds, provider/model selection, specialist personas, configuration reload and project/workspace state. - Closure path: no first-party operating path was found that distinguishes an external/future capability issue, generates an adaptation option, selects it and returns a changed capability or S3 regime into subsequent operation. - Why this is / is not agent-owned: cadis-memory can store candidate records, explicitly promote/reject them and inject already-confirmed capsules, but cadis-core only consumes confirmed memory. The standard runtime does not wire autonomous evidence-to-adaptation proposal/selection/promotion closure. - Evidence: crates/cadis-memory/src/lib.rs; crates/cadis-core/src/lib.rs. - Basis: explicit + structural absence -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material first-party identity/ultimate-policy authority loop is established for the declared CADIS operating boundary at the pinned revision. - Disturbance / variety regulated: not established at identity/ultimate-policy level. - Decisive decision or feedback right: no legitimate first-party ultimate authority is wired to adjudicate or amend the organization&#39;s governing identity/policy when such an issue arises. - Decision owner: none established. - Supporting / enforcement mechanisms: hardcoded/default CADIS identity prompt, specialist persona fields and agent.specialist.set, central policy engine, workspace grants, risk classes, approval state and ordinary model/provider configuration. - Closure path: no identity/ultimate-policy issue → legitimate authority → adjudication/amendment → subsequent-operation-under-new-policy chain is established. - Why this is / is not agent-owned: the named CADIS persona and parent-editable specialist persona configure operating roles; policy/approval components enforce already-selected constraints. Neither surface establishes ultimate-policy ownership merely because it changes prompts or blocks risky actions. - Evidence: crates/cadis-core/src/lib.rs; docs/29PROTOCOLFREEZE.md; crates/cadis-policy/src/lib.rs. - Basis: explicit + structural absence - Confidence: high - Caveats: agent.specialist.set and parent configuration can materially change behavior, but task/role/persona configuration is not automatically the organization&#39;s identity/ultimate-policy function.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/76cc1d6c195ab75cb4dea51f540dd3d685cf4700/assessments/cadis.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 76cc1d6c195ab75cb4dea51f540dd3d685cf4700\">76cc1d6 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-10-07T15:23:18+03:00\"><th scope=\"row\"><a href=\"https://github.com/hikaMaeng/ndx\" target=\"_blank\" rel=\"noopener\">ndx</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-07\">2026-10-07</time></td><td class=\"review-ref\"><a href=\"https://github.com/hikaMaeng/ndx/tree/b1cb16e9b3b3fcd514c9b71a199e10490b7900d7\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision b1cb16e9b3b3fcd514c9b71a199e10490b7900d7\">b1cb16e &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: perform coding work by interpreting a user request, selecting first-party tools, inspecting/modifying the workspace, running commands or sandboxed tools, and iterating from tool results. - Disturbance / variety regulated: task ambiguity, codebase state, tool/process results, errors, provider responses and evolving user/session context. - Decisive decision or feedback right: choose the next operational tool/action, interpret returned evidence, revise the approach, optionally delegate bounded work, and decide when the answer/work is complete. - Decision owner: the ndx root model-backed coding agent; child runAgent loops can own bounded delegated work. - Supporting / enforcement mechanisms: agent loop, tool registry/worker processes, Docker sandbox for eligible paths, session/runtime persistence, streaming events, max-turn guard, project/user context loading. - Closure path: user input → model decision → first-party tool action → tool result/history → next model decision → further action or terminal response. - Boundary reachability: runAgent is directly wired into the product runtime/session server and creates the first-party tool registry at the frozen revision. - Why this is / is not agent-owned: the runtime executes, persists and constrains operations, but the task-specific choice of tool, interpretation of results and next action comes from the model loop. - Evidence: loop.ts, tool-execution.ts, architecture.md. - Basis: explicit + structural. - Confidence: high. - Caveats: provider inference is external; sandbox/configuration and human environment bound reachable actions.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no sufficiently evidenced first-party inter-S1 interference-attenuation loop is established. - Disturbance / variety regulated: multiple child agents can share one cwd and therefore can in principle interfere through overlapping files/dependencies, but the reviewed ndx path does not establish a concrete first-party attenuation policy for that disturbance. - Decisive decision or feedback right: no S2-specific decision right is established beyond generic delegation, messaging/waiting and per-child lifecycle operations. - Decision owner: none established for S2. - Supporting / enforcement mechanisms: spawnagent, sendinput/sendmessage, waitagent, per-record state, CSV worker creation, generic tool-result feedback. - Closure path: not applicable. - Boundary reachability: no positive S2 path claimed. - Why this is / is not agent-owned: the model can create well-scoped children and wait/message them, but Methodology 0.3.6 does not treat delegation, messaging, shared state or sequencing alone as S2. The TypeScript controller supplies no disjoint worktree/file-ownership assignment, collision detector, dependency frontier, mutual-exclusion policy or repair/feedback loop tied to inter-S1 interference. - Evidence: agents.ts, subagents.ts, agent-loop-analysis.md. - Basis: structural. - Confidence: high. - Caveats: spawnagentsoncsv declares concurrency-related arguments at the tool-schema layer, but the reviewed TypeScript implementation iterates rows and calls spawnAgent without implementing an S2-specific interference controller.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: observe and regulate the live set of subordinate child-agent commitments during the current coding session. - Disturbance / variety regulated: running/completed/failed/closed child work, children that should be waited on or terminated, the need to launch additional bounded work, and settled children that need a subsequent turn. - Decisive decision or feedback right: inspect child lifecycle snapshots, decide to spawn additional children, wait on selected children, close/abort a selected active child, and start a subsequent turn for a settled child. - Decision owner: the root ndx model-backed agent through model-callable collaboration tools. - Supporting / enforcement mechanisms: shared SubAgentController, stable child ids, per-agent status/error/finalText timestamps, AbortController, child promises, listagents, waitagent, closeagent, resume/follow-up/input tools. - Closure path: root requests current agent-set/status evidence → model decides a current intervention → controller applies spawn/wait/close/resume/follow-up action → updated lifecycle/result evidence returns as a tool result → root decides subsequent work. - Boundary reachability: the collaboration tools are registered in the first-party tool registry and dispatch through ToolContext.agentController; both root runtime and nested child runs receive the shared controller. - Why this is / is not agent-owned: the TypeScript controller stores status and executes lifecycle operations, while the model chooses which child to observe, wait on, stop, resume or task next. Removing the model leaves lifecycle machinery without the same task-specific current-control judgment. - Whole-system current view: listagents returns snapshots for the controller&#39;s known agent set, including status, task prompt, final text/error and timestamps; waitagent returns selected current/final snapshots after a bounded wait. - Current-control decision scope: child spawn, selective wait, targeted close/abort, resume/reuse of a closed child record, and follow-up/input into a non-running child. The reviewed controller does not provide Rust Codex&#39;s full mailbox/watch graph, so the S3 claim is bounded to this implemented child set. - Evidence: subagents.ts, agents.ts, agent-loop-analysis.md. - Basis: explicit + structural. - Confidence: high. - Caveats: sendinput on an already-running child returns a queued status in the reviewed implementation without a Rust-style durable mailbox; S3 is therefore credited from the implemented view/wait/close/spawn/reuse control surface, not from unsupported live-message semantics.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no sufficiently independent first-party audit/reviewer loop with corrective closure is established inside the shipped ndx runtime boundary. - Disturbance / variety regulated: not established as S3. - Decisive decision or feedback right: none meeting S3 independence/closure. - Decision owner: none established. - Supporting / enforcement mechanisms: generic child-agent creation, model-pool field named reviewer, repository-development .codex/skills/code-review, builtin command metadata named review, ordinary tests/tool results. - Closure path: not applicable. - Boundary reachability: no positive S3 path claimed. - Why this is / is not agent-owned: naming/configuration surfaces do not instantiate a distinct reviewer owner. The reviewed TypeScript subagent path records agenttype metadata but launches the same runAgent config/client/tool environment; no first-party reviewer restriction, fresh evidence contract or returned veto/corrective gate is wired. - Evidence: subagents.ts, config/index.ts, session command registry. - Basis: structural. - Confidence: high. - Caveats: repository-maintainer code-review skills may help contributors review ndx itself, but they are excluded from the installed coding-agent organizational boundary and cannot donate S3.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no first-party external-and-prospective capability-adaptation loop is established. - Disturbance / variety regulated: not established as S4. - Decisive decision or feedback right: none for S4. - Decision owner: none established. - Supporting / enforcement mechanisms: AGENTS.md/skill discovery, provider/model settings, session history/logs, environment context and manual configuration. - Closure path: not applicable. - Boundary reachability: no positive S4 path claimed. - Why this is / is not agent-owned: ndx can load instructions/skills and users can alter configuration, but no reviewed first-party model loop autonomously identifies future/environmental change, generates an adaptation option and writes/promotes it into continuing product capability. - Evidence: initial-context/skill architecture described in agent-loop-analysis.md, architecture.md. - Basis: structural. - Confidence: high. - Caveats: reloadable project/user resources are operator-authored extensibility, not autonomous S4.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no runtime first-party identity/ultimate-policy governance loop is established. - Disturbance / variety regulated: not established as S5. - Decisive decision or feedback right: none for S5. - Decision owner: none established. - Supporting / enforcement mechanisms: configured instructions, permission/sandbox settings, project/user AGENTS.md, tool/MCP configuration and local user authority. - Closure path: not applicable. - Boundary reachability: no positive S5 path claimed. - Why this is / is not agent-owned: these mechanisms constrain or configure current operation; they do not grant a model-backed actor legitimate authority to decide ndx&#39;s ultimate identity/purpose/policy and return that decision as binding governance. - Evidence: config/index.ts, architecture.md. - Basis: structural. - Confidence: high. - Caveats: user/developer configuration is an external authority boundary, not by itself a parent-governed S5 loop under Methodology 0.3.6.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9b9fcf4c55f11bb9f24139040fce58f2bd1bea53/assessments/ndx.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9b9fcf4c55f11bb9f24139040fce58f2bd1bea53\">9b9fcf4 &#8599;</a></td></tr>"];
